function crc32Table() {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    table[n] = c >>> 0;
  }
  return table;
}

const CRC_TABLE = crc32Table();
const encoder = new TextEncoder();

function crc32(bytes) {
  let crc = 0xffffffff;
  for (let i = 0; i < bytes.length; i++) crc = CRC_TABLE[(crc ^ bytes[i]) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

function dosDateTime(date = new Date()) {
  const year = Math.max(1980, date.getFullYear());
  const time = ((date.getHours() & 0x1f) << 11) | ((date.getMinutes() & 0x3f) << 5) | ((Math.floor(date.getSeconds() / 2)) & 0x1f);
  const day = ((year - 1980) << 9) | (((date.getMonth() + 1) & 0x0f) << 5) | (date.getDate() & 0x1f);
  return { time, day };
}

function safePath(value = 'file.txt') {
  const normalized = String(value || 'file.txt')
    .replace(/\\/g, '/')
    .replace(/^\/+/, '')
    .split('/')
    .filter((part) => part && part !== '.' && part !== '..')
    .join('/');
  return normalized || 'file.txt';
}

function concat(parts) {
  const size = parts.reduce((sum, part) => sum + part.length, 0);
  const out = new Uint8Array(size);
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

function view(size) {
  const bytes = new Uint8Array(size);
  return { bytes, data: new DataView(bytes.buffer) };
}

export function createZipBlob(files = []) {
  const entries = files.map((file) => {
    const name = safePath(file.path || file.name || 'file.txt');
    const nameBytes = encoder.encode(name);
    const contentBytes = typeof file.content === 'string' ? encoder.encode(file.content) : new Uint8Array(file.content || []);
    return { name, nameBytes, contentBytes, crc: crc32(contentBytes) };
  });

  const localParts = [];
  const centralParts = [];
  let localOffset = 0;
  const stamp = dosDateTime();

  for (const entry of entries) {
    const local = view(30);
    local.data.setUint32(0, 0x04034b50, true);
    local.data.setUint16(4, 20, true);
    local.data.setUint16(6, 0x0800, true); // UTF-8 names
    local.data.setUint16(8, 0, true);      // store, no compression
    local.data.setUint16(10, stamp.time, true);
    local.data.setUint16(12, stamp.day, true);
    local.data.setUint32(14, entry.crc, true);
    local.data.setUint32(18, entry.contentBytes.length, true);
    local.data.setUint32(22, entry.contentBytes.length, true);
    local.data.setUint16(26, entry.nameBytes.length, true);
    local.data.setUint16(28, 0, true);
    localParts.push(local.bytes, entry.nameBytes, entry.contentBytes);

    const central = view(46);
    central.data.setUint32(0, 0x02014b50, true);
    central.data.setUint16(4, 20, true);
    central.data.setUint16(6, 20, true);
    central.data.setUint16(8, 0x0800, true);
    central.data.setUint16(10, 0, true);
    central.data.setUint16(12, stamp.time, true);
    central.data.setUint16(14, stamp.day, true);
    central.data.setUint32(16, entry.crc, true);
    central.data.setUint32(20, entry.contentBytes.length, true);
    central.data.setUint32(24, entry.contentBytes.length, true);
    central.data.setUint16(28, entry.nameBytes.length, true);
    central.data.setUint16(30, 0, true);
    central.data.setUint16(32, 0, true);
    central.data.setUint16(34, 0, true);
    central.data.setUint16(36, 0, true);
    central.data.setUint32(38, 0, true);
    central.data.setUint32(42, localOffset, true);
    centralParts.push(central.bytes, entry.nameBytes);

    localOffset += local.bytes.length + entry.nameBytes.length + entry.contentBytes.length;
  }

  const centralBytes = concat(centralParts);
  const end = view(22);
  end.data.setUint32(0, 0x06054b50, true);
  end.data.setUint16(4, 0, true);
  end.data.setUint16(6, 0, true);
  end.data.setUint16(8, entries.length, true);
  end.data.setUint16(10, entries.length, true);
  end.data.setUint32(12, centralBytes.length, true);
  end.data.setUint32(16, localOffset, true);
  end.data.setUint16(20, 0, true);

  return new Blob([...localParts, centralBytes, end.bytes], { type: 'application/zip' });
}

export function normalizeDownloadName(value = 'artifact') {
  return String(value || 'artifact')
    .trim()
    .replace(/[\\/:*?"<>|]+/g, '-')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '') || 'artifact';
}
