import { ProjectStore } from '../projects/project-store.js';

function normalizePath(path = '') {
  const parts = String(path).replace(/\\/g, '/').split('/').filter(Boolean);
  if (parts.some((p) => p === '..')) throw new Error('Parent-directory traversal is not allowed.');
  return parts.filter((p) => p !== '.');
}

async function resolveHandle(root, path, { createDir = false } = {}) {
  const parts = normalizePath(path);
  let dir = root;
  for (let i = 0; i < parts.length - 1; i++) dir = await dir.getDirectoryHandle(parts[i], { create: createDir });
  return { dir, name: parts.at(-1), parts };
}

async function readFile(root, path) {
  const { dir, name } = await resolveHandle(root, path);
  if (!name) throw new Error('A file path is required.');
  const handle = await dir.getFileHandle(name);
  const file = await handle.getFile();
  return file.text();
}

async function fileExists(root, path) {
  try { await readFile(root, path); return true; } catch { return false; }
}

async function writeTextFile(root, path, content) {
  const { name, parts } = await resolveHandle(root, path, { createDir: true });
  if (!name) throw new Error('A file path is required.');
  let writeDir = root;
  for (const part of parts.slice(0, -1)) writeDir = await writeDir.getDirectoryHandle(part, { create: true });
  const handle = await writeDir.getFileHandle(name, { create: true });
  const writable = await handle.createWritable();
  await writable.write(String(content ?? ''));
  await writable.close();
}

async function walk(dir, prefix = '', depth = 0, maxDepth = 6, out = [], maxEntries = 500) {
  if (depth > maxDepth || out.length >= maxEntries) return out;
  for await (const [name, handle] of dir.entries()) {
    if (out.length >= maxEntries) break;
    if (name === 'node_modules' || name === '.git' || name === 'dist') continue;
    const path = prefix ? `${prefix}/${name}` : name;
    out.push({ path, kind: handle.kind });
    if (handle.kind === 'directory') await walk(handle, path, depth + 1, maxDepth, out, maxEntries);
  }
  return out;
}

function globToRegExp(glob = '**/*') {
  const escaped = String(glob).replace(/\\/g, '/').replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*\*/g, '§§DOUBLESTAR§§').replace(/\*/g, '[^/]*').replace(/\?/g, '[^/]').replace(/§§DOUBLESTAR§§/g, '.*');
  return new RegExp(`^${escaped}$`, 'i');
}

export class ProjectWorkspace extends EventTarget {
  constructor(store = new ProjectStore()) {
    super();
    this.store = store;
    this.root = null;
    this.name = null;
    this.id = null;
    this.permission = 'none';
    this.store.addEventListener('change', () => this.dispatchEvent(new CustomEvent('projects', { detail: { projects: this.projects, activeId: this.id } })));
  }

  get available() { return typeof window.showDirectoryPicker === 'function'; }
  get projects() { return this.store.list(); }
  get activeProject() { return this.store.get(this.id) || null; }
  get instructions() { return this.activeProject?.instructions || ''; }
  get pinnedContext() { return this.activeProject?.pinnedContext || []; }
  get changedFiles() { return this.activeProject?.changedFiles || []; }
  get recentFiles() { return this.activeProject?.recentFiles || []; }
  get fileIndex() { return this.activeProject?.fileIndex || []; }

  async init() {
    await this.store.init();
    return this;
  }

  async ensurePermission(handle, { request = true } = {}) {
    if (!handle) return 'denied';
    const options = { mode: 'readwrite' };
    try {
      let state = await handle.queryPermission?.(options) || 'prompt';
      if (state !== 'granted' && request) state = await handle.requestPermission?.(options) || state;
      return state;
    } catch { return 'prompt'; }
  }

  async chooseDirectory() {
    if (!this.available) throw new Error('This browser does not expose the File System Access API. Use a Chromium-based browser for editable Work projects.');
    const handle = await window.showDirectoryPicker({ mode: 'readwrite' });
    const record = await this.store.addHandle(handle);
    await this.activate(record.id, { requestPermission: true });
    return this.root;
  }

  async activate(id, { requestPermission = true, quiet = false } = {}) {
    const record = await this.store.activate(id);
    if (!record) return null;
    this.id = record.id;
    this.name = record.name;
    this.permission = await this.ensurePermission(record.handle, { request: requestPermission });
    this.root = this.permission === 'granted' ? record.handle : null;
    if (this.root) {
      try { await this.refreshFileIndex(record.id, { root: this.root }); } catch {}
    }
    if (!quiet) this.dispatchEvent(new CustomEvent('project', { detail: { id: this.id, name: this.name, permission: this.permission } }));
    return record;
  }

  async removeProject(id) {
    const wasActive = id === this.id;
    await this.store.remove(id);
    if (wasActive) {
      this.root = null; this.name = null; this.id = null; this.permission = 'none';
      if (this.store.activeProjectId) await this.activate(this.store.activeProjectId, { requestPermission: false, quiet: true });
      this.dispatchEvent(new CustomEvent('project', { detail: { id: this.id, name: this.name, permission: this.permission } }));
    }
  }

  async updateProject(patch) {
    if (!this.id) return null;
    const record = await this.store.patch(this.id, patch);
    if (record) this.name = record.name;
    this.dispatchEvent(new CustomEvent('project', { detail: { id: this.id, name: this.name, permission: this.permission } }));
    return record;
  }

  async clearChanges() { if (this.id) await this.store.clearChanges(this.id); }

  async deactivate({ quiet = false } = {}) {
    await this.store.deactivate();
    this.root = null; this.name = null; this.id = null; this.permission = 'none';
    if (!quiet) this.dispatchEvent(new CustomEvent('project', { detail: { id: null, name: null, permission: 'none' } }));
  }

  clear() {
    // Backward-compatible immediate clear for callers that cannot await. Persist
    // the inactive state too so a deliberately deactivated project does not
    // silently resurrect after a reload.
    this.root = null; this.name = null; this.id = null; this.permission = 'none';
    this.store.deactivate().catch(() => {});
    this.dispatchEvent(new CustomEvent('project', { detail: { id: null, name: null, permission: 'none' } }));
  }

  async rootForProject(projectId = this.id, { requestPermission = false } = {}) {
    const record = this.store.get(projectId);
    if (!record) return null;
    if (projectId === this.id && this.root) return this.root;
    const permission = await this.ensurePermission(record.handle, { request: requestPermission });
    return permission === 'granted' ? record.handle : null;
  }

  async refreshFileIndex(projectId = this.id, { root = null, maxDepth = 4, maxEntries = 250 } = {}) {
    if (!projectId) return [];
    const handle = root || await this.rootForProject(projectId, { requestPermission: false });
    if (!handle) return this.store.get(projectId)?.fileIndex || [];
    const entries = await walk(handle, '', 0, maxDepth, [], maxEntries);
    await this.store.noteFileIndex(projectId, entries);
    return entries;
  }

  async projectSnapshot(projectId = this.id, { refresh = true, maxEntries = 120 } = {}) {
    const record = this.store.get(projectId);
    if (!record) return null;
    let entries = record.fileIndex || [];
    if (refresh) {
      try { entries = await this.refreshFileIndex(projectId, { maxDepth: 4, maxEntries: Math.max(maxEntries, 160) }); } catch {}
    }
    const files = entries.filter((entry) => entry.kind === 'file').slice(0, maxEntries).map((entry) => entry.path);
    const directories = entries.filter((entry) => entry.kind === 'directory').slice(0, 48).map((entry) => entry.path);
    return {
      id: record.id,
      name: record.name,
      files,
      directories,
      indexedCount: entries.length,
      lastScannedAt: record.lastScannedAt || 0,
    };
  }

  requireRoot() {
    if (!this.id) throw new Error('No Work project is active.');
    if (!this.root) throw new Error(`Project “${this.name}” needs filesystem permission. Open Projects and reconnect it.`);
    return this.root;
  }

  get definitions() {
    if (!this.root) return [];
    return [
      { type: 'function', function: { name: 'list_directory', description: 'List files and folders inside the active project. Use this first when the user refers to the current app, game, UI, codebase, or project without naming an exact file.', parameters: { type: 'object', properties: { path: { type: 'string', description: 'Project-relative directory. Empty string means project root.' } } } } },
      { type: 'function', function: { name: 'file_glob_search', description: 'Find files in the active project by glob pattern. Examples: **/*.js, src/**/*.ts, *.html.', parameters: { type: 'object', properties: { pattern: { type: 'string' }, max_results: { type: 'number' } }, required: ['pattern'] } } },
      { type: 'function', function: { name: 'read_file', description: 'Read a UTF-8 text file from the active project.', parameters: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] } } },
      { type: 'function', function: { name: 'grep_search', description: 'Search text files in the active project for a literal query and return matching lines.', parameters: { type: 'object', properties: { query: { type: 'string' }, path: { type: 'string' }, max_results: { type: 'number' } }, required: ['query'] } } },
      { type: 'function', function: { name: 'write_file', description: 'Create or overwrite a UTF-8 file in the active project. User approval is required and the change is tracked in Changed Files.', parameters: { type: 'object', properties: { path: { type: 'string' }, content: { type: 'string' } }, required: ['path', 'content'] } } },
      { type: 'function', function: { name: 'edit_file', description: 'Edit an active-project file by replacing exact text. User approval is required and the change is tracked.', parameters: { type: 'object', properties: { path: { type: 'string' }, search: { type: 'string' }, replace: { type: 'string' }, replace_all: { type: 'boolean' } }, required: ['path', 'search', 'replace'] } } },
      { type: 'function', function: { name: 'get_info', description: 'Return active BlackRiver project metadata and browser-safe capabilities.', parameters: { type: 'object', properties: {} } } },
    ];
  }

  async execute(name, args = {}, { approve, projectId: requestedProjectId } = {}) {
    const projectId = requestedProjectId !== undefined ? requestedProjectId : this.id;
    const record = this.store.get(projectId);
    if (!record) throw new Error('The Work project for this generation is no longer available.');
    let root = projectId === this.id ? this.root : null;
    if (!root) {
      const permission = await this.ensurePermission(record.handle, { request: false });
      if (permission === 'granted') root = record.handle;
    }
    if (!root) throw new Error(`Project “${record.name}” is not currently authorized. Reopen it from Projects and retry.`);
    switch (name) {
      case 'get_info': return { project_id: projectId, project: record.name, root_access: 'browser-granted', instructions: record.instructions || '', pinned_context: record.pinnedContext || [], indexed_files: (record.fileIndex || []).filter((entry) => entry.kind === 'file').slice(0, 120).map((entry) => entry.path), recent_files: (record.recentFiles || []).slice(0, 12), changed_files: (record.changedFiles || []).map(({ path, status }) => ({ path, status })), capabilities: ['list_directory', 'file_glob_search', 'read_file', 'grep_search', 'write_file', 'edit_file'], shell: false };
      case 'file_glob_search': {
        const all = await walk(root, '', 0, 8, [], 500); const pattern = String(args.pattern || '**/*').replace(/\\/g, '/').replace(/^\.\//, ''); const regex = globToRegExp(pattern); const limit = Math.max(1, Math.min(Number(args.max_results) || 200, 500)); const matches = all.filter((entry) => entry.kind === 'file' && regex.test(entry.path)).slice(0, limit).map((entry) => entry.path); return { pattern, matches, truncated: matches.length >= limit };
      }
      case 'list_directory': {
        let dir = root; for (const part of normalizePath(args.path || '')) dir = await dir.getDirectoryHandle(part); const entries = []; for await (const [entryName, handle] of dir.entries()) entries.push({ name: entryName, kind: handle.kind }); entries.sort((a, b) => a.kind === b.kind ? a.name.localeCompare(b.name) : a.kind === 'directory' ? -1 : 1); return { path: args.path || '.', entries };
      }
      case 'read_file': {
        const content = await readFile(root, args.path); await this.store.noteRecentFile(projectId, args.path); return { path: args.path, content };
      }
      case 'grep_search': {
        const all = await walk(root, '', 0, 6, [], 500); const prefix = (args.path || '').replace(/\\/g, '/').replace(/^\/|\/$/g, ''); const query = String(args.query || ''); const limit = Math.max(1, Math.min(Number(args.max_results) || 50, 200)); const matches = []; const textExt = /\.(txt|md|js|mjs|cjs|ts|tsx|jsx|json|html|css|scss|py|rs|cpp|c|h|hpp|java|go|toml|yaml|yml|ini|bat|ps1|sh|xml|svg)$/i;
        for (const entry of all) { if (matches.length >= limit) break; if (entry.kind !== 'file' || !textExt.test(entry.path) || (prefix && !entry.path.startsWith(prefix))) continue; try { const content = await readFile(root, entry.path); content.split(/\r?\n/).forEach((line, index) => { if (matches.length < limit && line.includes(query)) matches.push({ path: entry.path, line: index + 1, text: line.slice(0, 500) }); }); } catch {} }
        return { query, matches, truncated: matches.length >= limit };
      }
      case 'write_file': {
        const existed = await fileExists(root, args.path); const before = existed ? await readFile(root, args.path) : null; const ok = await approve?.({ name, args, summary: `${existed ? 'Write' : 'Create'} ${args.path}` }); if (ok === false) return { status: 'denied', path: args.path }; const after = String(args.content ?? ''); await writeTextFile(root, args.path, after); await this.store.noteChange(projectId, { path: args.path, before, after, status: existed ? 'modified' : 'added' }); await this.refreshFileIndex(projectId, { root, maxDepth: 4, maxEntries: 250 }); return { status: 'ok', path: args.path, bytes: new Blob([after]).size, change: existed ? 'modified' : 'added' };
      }
      case 'edit_file':
      case 'replace_in_file': {
        const before = await readFile(root, args.path); const search = String(args.search ?? ''); if (!search) throw new Error('Search text cannot be empty.'); const count = before.split(search).length - 1; if (!count) return { status: 'not_found', path: args.path, occurrences: 0 }; const ok = await approve?.({ name, args: { ...args, content: undefined }, summary: `Edit ${args.path} (${args.replace_all ? count : 1} replacement${count === 1 ? '' : 's'})` }); if (ok === false) return { status: 'denied', path: args.path }; const after = args.replace_all ? before.split(search).join(String(args.replace ?? '')) : before.replace(search, String(args.replace ?? '')); await writeTextFile(root, args.path, after); await this.store.noteChange(projectId, { path: args.path, before, after, status: 'modified' }); await this.refreshFileIndex(projectId, { root, maxDepth: 4, maxEntries: 250 }); return { status: 'ok', path: args.path, occurrences: args.replace_all ? count : 1, change: 'modified' };
      }
      default: throw new Error(`Unknown Work tool: ${name}`);
    }
  }

  async revertChange(path) {
    const root = this.requireRoot(); const entry = this.changedFiles.find((item) => item.path === path); if (!entry) throw new Error('Tracked change not found.');
    if (entry.status === 'added' && entry.before == null) {
      const { dir, name } = await resolveHandle(root, path); await dir.removeEntry(name);
    } else {
      await writeTextFile(root, path, entry.before ?? '');
    }
    const projectRecord = this.activeProject; projectRecord.changedFiles = projectRecord.changedFiles.filter((item) => item.path !== path); await this.store.persistProject(projectRecord); await this.refreshFileIndex(this.id, { root, maxDepth: 4, maxEntries: 250 }); this.store.dispatchEvent(new Event('change'));
    return true;
  }
}
