import { OpenAICompatibleRuntime } from './openai-compatible-runtime.js';

export class ProviderRouter extends EventTarget {
  constructor(localRuntime, providerStore) {
    super();
    this.local = localRuntime;
    this.store = providerStore;
    this.api = new OpenAICompatibleRuntime();
    this.sampling = { ...localRuntime.sampling };
    this.api.addEventListener('context', (event) => this.dispatchEvent(new CustomEvent('context', { detail: event.detail })));

    localRuntime.addEventListener('status', (event) => {
      // Loading a Wllama model always makes the local runtime active.
      if (event.detail?.state === 'ready' && event.detail?.loaded) this.store.selectWllama();
      this.dispatchEvent(new CustomEvent('status', { detail: event.detail }));
    });
    localRuntime.addEventListener('hardware', (event) => this.dispatchEvent(new CustomEvent('hardware', { detail: event.detail })));
    localRuntime.addEventListener('cache-error', (event) => this.dispatchEvent(new CustomEvent('cache-error', { detail: event.detail })));
    providerStore.addEventListener('change', () => {
      this.syncApiSelection();
      this.dispatchEvent(new CustomEvent('provider', { detail: this.selection }));
    });
    this.syncApiSelection();
  }

  get selection() { return this.store.selection; }
  get isApi() { return this.selection?.kind === 'api'; }
  get isLocal() { return !this.isApi; }
  get hardware() { return this.local.hardware; }
  get runtimeParams() { return this.local.runtimeParams; }
  get modelManager() { return this.local.modelManager; }
  get localIsLoaded() { return this.local.isLoaded; }

  syncApiSelection() {
    if (!this.isApi) return;
    const provider = this.store.get(this.selection.providerId);
    this.api.configure(provider, this.selection.modelId || provider?.lastModelId || '');
    // Local Wllama's max_tokens is a load/generation preference, not an API
    // provider setting. Never propagate it across the provider boundary.
    const { max_tokens: _localOnlyMaxTokens, ...apiSampling } = this.sampling;
    this.api.setSampling(apiSampling);
  }

  get isLoaded() { return this.isApi ? this.api.isLoaded : this.local.isLoaded; }
  get loaded() { return this.isApi ? this.api.loaded : this.local.loaded; }
  get contextSize() { return this.isApi ? this.api.contextSize : this.local.contextSize; }
  get loadedContextInfo() { return this.isApi ? null : this.local.loadedContextInfo; }
  get capabilities() { return this.isApi ? this.api.capabilities : this.local.capabilities; }
  get supportsWebGPU() { return this.local.supportsWebGPU; }
  get backendLabel() {
    if (this.isApi) return `${this.api.provider?.name || 'API'} · API`;
    return this.local.hardware.adapter ? 'Local · WebGPU' : this.local.isLoaded ? 'Local · CPU' : 'Local';
  }
  get inferenceLabel() {
    if (this.isApi) return `${this.api.provider?.name || 'API'} · ${this.api.modelId || 'model'}`;
    return `Wllama 3.6 · ${this.local.hardware.adapter ? 'WebGPU' : 'local'}`;
  }

  selectApi(providerId, modelId) {
    this.store.selectApi(providerId, modelId);
    this.syncApiSelection();
  }
  selectLocal() { this.store.selectWllama(); }

  async discoverModels(provider) { return this.api.discoverModels(provider); }
  async refreshActiveModelInfo() {
    if (this.isApi) return this.api.refreshModelInfo();
    return { contextSize: this.local.contextSize, payload: this.local.loadedContextInfo };
  }
  async reloadLocalCurrent(overrides = {}) {
    const result = await this.local.reloadCurrent(overrides);
    this.store.selectWllama();
    return result;
  }
  get canReloadLocalCurrent() { return !!this.local.reloadSpec; }
  async probeWebGPU(force = false) { return this.local.probeWebGPU(force); }
  async listCachedModels() { return this.local.listCachedModels(); }
  setRuntimeParams(patch) { this.local.setRuntimeParams(patch); }
  setSampling(patch) {
    this.sampling = { ...this.sampling, ...patch };
    this.local.setSampling(patch);
    const { max_tokens: _localOnlyMaxTokens, ...apiPatch } = patch || {};
    this.api.setSampling(apiPatch);
  }

  async loadLocal(...args) { const result = await this.local.loadLocal(...args); this.store.selectWllama(); return result; }
  async loadFromUrls(...args) { const result = await this.local.loadFromUrls(...args); this.store.selectWllama(); return result; }
  async loadFromHF(...args) { const result = await this.local.loadFromHF(...args); this.store.selectWllama(); return result; }

  async chat(params, onChunk) { return this.isApi ? this.api.chat(params, onChunk) : this.local.chat(params, onChunk); }
  stop() { return this.isApi ? this.api.stop() : this.local.stop(); }
  async unload() {
    if (this.isApi) {
      this.store.selectWllama();
      this.dispatchEvent(new CustomEvent('status', { detail: { state: this.local.isLoaded ? 'ready' : 'idle', message: this.local.isLoaded ? `${this.local.loaded?.name} loaded` : 'No model loaded', loaded: this.local.loaded } }));
      return;
    }
    return this.local.unload();
  }
}
