function setMode(mode, { persist = true } = {}) {
  const value = mode === 'work' ? 'work' : 'chat';
  if (persist) store.switchMode(value);
  document.body.dataset.mode = value;
  document.querySelectorAll('.mode-tab').forEach((btn) => btn.classList.toggle('active', btn.dataset.mode === value));

  // Chat and Work are two context lanes over the SAME loaded Wllama model.
  // Switching tabs never unloads/reloads weights; only the active message history changes.
  if (value === 'chat') hideArtifactPane({ preserveActive: true });
  renderEmptyState();
  updatePlaceholder();
  syncReasoningUi();
  syncContextUi();
  syncArtifactReopenButton();
}

function updatePlaceholder() {
  els.promptInput.placeholder = store.state.mode === 'work' ? 'Work on anything' : 'Ask BlackRiver';
}

function renderEmptyState() {
  const conv = store.activeConversation;
  const empty = !conv || conv.messages.length === 0;
  els.emptyState.classList.toggle('hidden', !empty);
  if (store.state.mode === 'work') {
    els.emptyTitle.textContent = 'What should we work on?';
    els.emptySubtitle.textContent = project.root ? `Project connected: ${project.name}` : project.name ? `Project saved: ${project.name} · reconnect required.` : 'Create an artifact or connect a local project.';
  } else {
    els.emptyTitle.textContent = 'Ready when you are.';
    els.emptySubtitle.textContent = 'Private local intelligence, running on your hardware.';
  }
}

function renderRecents() {
  // Recents are global, exactly like the stable 1.6.5 shell. An active Project
  // scopes Work execution, not sidebar visibility. Updated conversations sort
  // to the top so returning to an old chat and continuing it promotes it.
  const items = store.recentConversations(20);
  els.recents.innerHTML = items.map((c) => {
    const isGenerating = generating && c.id === generationConversationId;
    const title = escapeHtml(c.title || 'New chat');
    const projectName = c.projectId ? project.projects.find((item) => item.id === c.projectId)?.name : '';
    const contextTitle = c.mode === 'work' ? ` · Work${projectName ? ` · ${projectName}` : ''}` : ' · Chat';
    return `
    <div class="recent-entry ${c.id === store.state.activeConversationId ? 'active' : ''} ${isGenerating ? 'generating' : ''}" data-recent-id="${c.id}">
      <button class="recent" data-conversation="${c.id}" title="${title}${escapeHtml(contextTitle)}${isGenerating ? ' · Generating' : ''}">
        <span>${title}</span>
      </button>
      ${isGenerating ? '<span class="recent-generation-indicator" role="status" aria-label="Generating response" title="Generating response"><span></span></span>' : ''}
      <button class="recent-more" data-conversation-menu="${c.id}" aria-label="Conversation options" title="Conversation options">${icon('more', 17)}</button>
    </div>`;
  }).join('');
  els.recents.querySelectorAll('[data-conversation]').forEach((btn) => {
    btn.onclick = async () => {
      closeFloatingMenu();
      const conv = store.activate(btn.dataset.conversation);
      if (conv?.mode === 'work') {
        if (conv.projectId) {
          try { await project.activate(conv.projectId, { requestPermission: true, quiet: true }); } catch {}
        } else if (project.id) await project.deactivate({ quiet: true });
      }
      artifacts.close();
      closeMobileSidebar();
      renderAll();
    };
  });
  els.recents.querySelectorAll('[data-conversation-menu]').forEach((btn) => {
    btn.onclick = (event) => {
      event.stopPropagation();
      openConversationMenu(btn.dataset.conversationMenu, btn);
    };
  });
}

function renderToolEvents(tools = []) {
  const rows = [];
  const pending = [];

  for (const tool of tools) {
    if (tool.phase === 'call') {
      pending.push(tool);
      continue;
    }
    if (tool.phase !== 'result') continue;

    // Pair the result with the most recent unresolved call of the same tool so
    // the UI shows one compact lifecycle row instead of a call/result duplicate.
    const idx = [...pending].reverse().findIndex((p) => p.name === tool.name);
    if (idx >= 0) pending.splice(pending.length - 1 - idx, 1);
    rows.push({ ...tool, pending: false });
  }
  rows.push(...pending.map((tool) => ({ ...tool, pending: true })));

  if (!rows.length) return '';
  return `<div class="tool-events">${rows.map((tool) => `
    <div class="tool-event ${tool.pending ? 'pending' : ''} ${tool.result?.error ? 'error' : ''}">
      <span class="tool-icon">${tool.pending ? '<span class="mini-spinner"></span>' : (tool.result?.error ? '!' : '✓')}</span>
      <span class="tool-copy"><strong>${escapeHtml(tool.pending ? toolPendingLabel(tool.name) : toolLabel(tool.name))}</strong>${toolDetail(tool) ? `<small>${escapeHtml(toolDetail(tool))}</small>` : ''}</span>
    </div>`).join('')}</div>`;
}

function formatCompactNumber(value = 0) {
  const n = Number(value) || 0;
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}m`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 10_000 ? 0 : 1)}k`;
  return String(Math.round(n));
}

function formatElapsed(ms = 0) {
  const seconds = Math.max(0, Number(ms) || 0) / 1000;
  return seconds < 10 ? `${seconds.toFixed(1)}s` : `${Math.round(seconds)}s`;
}

function isNearBottom() {
  const distance = els.scroller.scrollHeight - els.scroller.scrollTop - els.scroller.clientHeight;
  return distance < 130;
}

function scrollConversation({ force = false } = {}) {
  if (force || isNearBottom()) els.scroller.scrollTop = els.scroller.scrollHeight;
}

function reasoningHtml(message, { streaming = false } = {}) {
  const reasoning = String(message.reasoning || '').trim();
  const elapsed = formatElapsed(message.elapsedMs || 0);
  if (!reasoning) return '';
  const live = streaming && message.live;
  const summary = live ? `Thinking · ${elapsed}` : `Thought for ${elapsed}`;
  const ui = reasoningUiState.get(message.id) || { open: false, follow: true };
  return `<details class="reasoning ${live ? 'live' : ''}" data-reasoning-id="${message.id}" ${ui.open ? 'open' : ''}><summary><span class="thinking-dot"></span><span>${summary}</span></summary><div class="reasoning-body">${escapeHtml(reasoning)}</div></details>`;
}

function reasoningState(messageId) {
  let state = reasoningUiState.get(messageId);
  if (!state) {
    state = { open: false, follow: true };
    reasoningUiState.set(messageId, state);
  }
  return state;
}

function bindReasoningInteractions(root = document) {
  root.querySelectorAll?.('.reasoning[data-reasoning-id]').forEach((details) => {
    if (details.dataset.reasoningBound === '1') return;
    details.dataset.reasoningBound = '1';
    const messageId = details.dataset.reasoningId;
    const body = details.querySelector('.reasoning-body');
    const state = reasoningState(messageId);
    details.open = !!state.open;

    details.addEventListener('toggle', () => {
      state.open = details.open;
      if (details.open) {
        // Opening a live thought should immediately reveal the newest token and
        // then keep following it, exactly like a streaming terminal tail.
        state.follow = true;
        requestAnimationFrame(() => {
          const currentBody = details.querySelector('.reasoning-body');
          if (currentBody) currentBody.scrollTop = currentBody.scrollHeight;
        });
      }
    });

    body?.addEventListener('scroll', () => {
      const distance = body.scrollHeight - body.scrollTop - body.clientHeight;
      state.follow = distance < 28;
    }, { passive: true });
  });
}

function updateReasoningDom(row, message, { streaming = false } = {}) {
  const slot = row?.querySelector('.reasoning-slot');
  if (!slot) return;
  const text = String(message.reasoning || '').trim();
  if (!text) {
    slot.innerHTML = '';
    return;
  }

  const live = streaming && message.live;
  const elapsed = formatElapsed(message.elapsedMs || 0);
  const summaryText = live ? `Thinking · ${elapsed}` : `Thought for ${elapsed}`;
  let details = slot.querySelector('.reasoning[data-reasoning-id]');
  if (!details) {
    slot.innerHTML = reasoningHtml(message, { streaming });
    bindReasoningInteractions(slot);
    details = slot.querySelector('.reasoning[data-reasoning-id]');
  }
  if (!details) return;

  const state = reasoningState(message.id);
  details.classList.toggle('live', live);
  details.open = !!state.open;
  const summary = details.querySelector('summary span:nth-child(2)');
  if (summary) summary.textContent = summaryText;
  const body = details.querySelector('.reasoning-body');
  if (body && body.textContent !== text) {
    const previousTop = body.scrollTop;
    body.textContent = text;
    if (!state.follow) body.scrollTop = previousTop;
  }

  if (body && details.open && state.follow) {
    requestAnimationFrame(() => {
      // Do not replace the <details> node while tokens stream. Replacing it was
      // resetting the internal scrollbar to the top on every token.
      body.scrollTop = body.scrollHeight;
    });
  }
}

function activityHtml(message) {
  if (!message.live) return '';
  const label = escapeHtml(message.activity || 'Thinking');
  const phase = escapeHtml(message.phase || 'prefill');
  return `<div class="live-activity ${phase}"><span class="activity-orb"><span></span></span><span class="activity-label">${label}</span><span class="activity-elapsed">${formatElapsed(message.elapsedMs || 0)}</span></div>`;
}

function formatInferenceCaption(metrics = lastInferenceMetrics) {
  if (!metrics) return runtime.inferenceLabel;
  const ctx = Number(metrics.contextSize || runtime.contextSize || 0);
  const used = Number(metrics.used || 0);
  const gen = Number(metrics.generationTpsLive || metrics.generationTps || 0);
  const prompt = Number(metrics.promptTps || 0);
  const speed = gen > 0 ? `${gen.toFixed(gen >= 100 ? 0 : 1)} tok/s` : prompt > 0 ? `${prompt.toFixed(prompt >= 100 ? 0 : 1)} tok/s prefill` : '';
  const context = ctx ? `${formatCompactNumber(used)} / ${formatCompactNumber(ctx)} ctx` : '';
  return [speed, context].filter(Boolean).join(' · ') || runtime.inferenceLabel;
}

function updateInferenceCaption(metrics = lastInferenceMetrics) {
  if (metrics) lastInferenceMetrics = { ...(lastInferenceMetrics || {}), ...metrics };
  els.composerCaption.textContent = formatInferenceCaption(lastInferenceMetrics);
  const m = lastInferenceMetrics;
  if (m) {
    const remaining = Number(m.remaining || 0);
    const cache = Number(m.cachedTokens || 0);
    const live = Number(m.generationTpsLive || 0);
    const average = Number(m.generationTpsAverage || m.generationTps || 0);
    els.composerCaption.title = [
      m.promptTps ? `Prefill ${m.promptTps.toFixed(1)} tok/s` : '',
      live ? `Generation ${live.toFixed(1)} tok/s live (3s)` : m.generationTps ? `Generation ${m.generationTps.toFixed(1)} tok/s` : '',
      live && average ? `Average ${average.toFixed(1)} tok/s` : '',
      cache ? `${formatCompactNumber(cache)} cached tokens` : '',
      m.contextSize ? `${formatCompactNumber(remaining)} context tokens remaining` : '',
    ].filter(Boolean).join(' · ');
  } else {
    els.composerCaption.title = '';
  }
  syncContextUi();
}

const CONTEXT_PRESETS = Object.freeze([8192, 16384, 32768, 65536, 131072, 262144]);

function currentContextSize() {
  return Number(lastInferenceMetrics?.contextSize || runtime.contextSize || (runtime.isLocal ? store.state.settings.context : 0)) || 0;
}

function syncContextSelect(value) {
  if (!els.contextSelect) return;
  const current = Number(value || 0);
  const values = [...CONTEXT_PRESETS];
  if (current > 0 && !values.includes(current)) values.push(current);
  values.sort((a, b) => a - b);
  els.contextSelect.innerHTML = values.map((size) => `<option value="${size}" ${size === current ? 'selected' : ''}>${formatCompactNumber(size)} tokens</option>`).join('');
}

function syncContextUi() {
  if (!els.contextMeterBtn) return;
  const ctx = currentContextSize();
  const used = Number(lastInferenceMetrics?.used || 0);
  const remaining = ctx > 0 ? Math.max(0, ctx - used) : 0;
  const pct = ctx > 0 ? Math.max(0, Math.min(100, (used / ctx) * 100)) : 0;
  const pctLabel = `${Math.round(pct)}%`;
  const output = runtime.isApi
    ? 0
    : Number(store.state.settings.maxTokens || runtime.sampling?.max_tokens || 0);
  const live = Number(lastInferenceMetrics?.generationTpsLive || lastInferenceMetrics?.generationTps || 0);
  const average = Number(lastInferenceMetrics?.generationTpsAverage || 0);

  els.contextMeterRing.style.setProperty('--ctx-pct', `${pct}%`);
  els.contextOverviewRing.style.setProperty('--ctx-pct', `${pct}%`);
  els.contextPercent.textContent = pctLabel;
  els.contextOverviewPct.textContent = pctLabel;
  els.contextUsed.textContent = used ? formatCompactNumber(used) : '0';
  els.contextRemaining.textContent = ctx ? formatCompactNumber(remaining) : '—';
  els.contextTotal.textContent = ctx ? formatCompactNumber(ctx) : '—';
  els.contextOutput.textContent = runtime.isApi ? (runtime.api?.isLlamaCpp ? 'Server' : 'Provider') : (output ? formatCompactNumber(output) : '—');
  const cached = Number(lastInferenceMetrics?.cachedTokens || 0);
  const prefill = Number(lastInferenceMetrics?.promptTps || 0);
  els.contextCached.textContent = cached ? formatCompactNumber(cached) : '—';
  els.contextPrefill.textContent = prefill ? `${prefill.toFixed(prefill >= 100 ? 0 : 1)}/s` : '—';
  els.contextSpeed.textContent = live ? `${live.toFixed(1)} tok/s` : '—';
  els.contextAverageSpeed.textContent = average && live ? `avg ${average.toFixed(1)}` : '';
  els.contextMeterBtn.title = ctx
    ? `Context ${formatCompactNumber(used)} / ${formatCompactNumber(ctx)} · ${pctLabel}`
    : 'Context window';

  if (runtime.isApi) {
    const isLlama = !!runtime.api?.isLlamaCpp;
    els.contextSource.textContent = isLlama ? `${runtime.api.provider?.name || 'llama.cpp'} · server` : `${runtime.api?.provider?.name || 'API'} · provider`;
    els.contextSetting.classList.add('readonly');
    els.contextSelect.disabled = true;
    els.contextApplyBtn.disabled = true;
    syncContextSelect(ctx || Number(store.state.settings.context || 32768));
    els.contextNote.textContent = isLlama
      ? (ctx ? 'Server context is read from llama.cpp. BlackRiver does not send the local Wllama Context/Max output values to this API; your llama.cpp INI/preset remains authoritative.' : 'Context is owned by the llama.cpp server. BlackRiver does not override it; open this panel again after the model is ready to sync it.')
      : 'This provider owns its own context/output policy. Local Wllama Advanced limits are never forwarded to API providers.';
  } else {
    const loadedName = runtime.local?.loaded?.name || 'BlackRiver Local';
    els.contextSource.textContent = runtime.local?.isLoaded ? `${loadedName} · Wllama` : 'BlackRiver Local · next load';
    els.contextSetting.classList.remove('readonly');
    els.contextSelect.disabled = false;
    els.contextApplyBtn.disabled = false;
    syncContextSelect(ctx || Number(store.state.settings.context || 32768));
    els.contextNote.textContent = 'Changing the local window also sets Max output to the same value. A loaded Wllama model must reload; conversations and artifacts stay saved.';
  }
}

async function refreshContextInfo() {
  if (runtime.isApi) {
    await runtime.refreshActiveModelInfo().catch(() => null);
  }
  syncContextUi();
}

function setContextPopover(open) {
  contextPopoverOpen = !!open;
  els.contextPopover.classList.toggle('hidden', !contextPopoverOpen);
  els.contextPopover.setAttribute('aria-hidden', String(!contextPopoverOpen));
  els.contextMeterBtn.setAttribute('aria-expanded', String(contextPopoverOpen));
  if (contextPopoverOpen) refreshContextInfo();
}

async function applyContextSelection() {
  if (runtime.isApi) return;
  if (generating) { toast('Stop generation before changing context.', 'info'); return; }
  const value = Math.max(1024, Number(els.contextSelect.value) || 32768);
  const current = Number(runtime.local?.contextSize || store.state.settings.context || 0);
  if (runtime.local?.isLoaded && value !== current) {
    const modelName = runtime.local.loaded?.name || 'the local model';
    const confirmed = window.confirm(`Change context to ${value.toLocaleString()} tokens?\n\n${modelName} must reload to apply the new context. Your Chat/Work conversations and artifacts stay saved.`);
    if (!confirmed) { syncContextUi(); return; }
  }

  store.updateSettings({ context: value, maxTokens: value });
  runtime.setRuntimeParams({ n_ctx: value });
  runtime.setSampling({ max_tokens: value });
  lastInferenceMetrics = null;
  setContextPopover(false);

  if (runtime.local?.isLoaded) {
    try {
      els.contextMeterBtn.disabled = true;
      await runtime.reloadLocalCurrent({ n_ctx: value });
      toast(`Context reloaded · ${formatCompactNumber(value)} tokens`, 'success');
    } catch (error) {
      toast(errorMessage(error), 'error');
    } finally {
      els.contextMeterBtn.disabled = false;
      syncContextUi();
    }
  } else {
    toast(`Context set to ${formatCompactNumber(value)} · applies on next local load`, 'success');
    syncContextUi();
  }
}

function startActivityTicker(message, conversationId = generationConversationId) {
  clearInterval(activityTicker);
  activityTicker = setInterval(() => {
    if (!message.live) return;
    message.elapsedMs = performance.now() - activeTurnStart;
    if (conversationId && store.state.activeConversationId !== conversationId) return;
    const row = document.querySelector(`[data-message-id="${CSS.escape(message.id)}"]`);
    row?.querySelectorAll('.activity-elapsed').forEach((el) => { el.textContent = formatElapsed(message.elapsedMs); });
    const summary = row?.querySelector('.reasoning.live summary span:nth-child(2)');
    if (summary) summary.textContent = `Thinking · ${formatElapsed(message.elapsedMs)}`;
  }, 100);
}

function stopActivityTicker() {
  clearInterval(activityTicker);
  activityTicker = null;
}

function conversationNavigatorSnippet(text, maxLength = 72) {
  const clean = String(text || '').replace(/\s+/g, ' ').trim();
  if (!clean) return 'Untitled turn';
  return clean.length <= maxLength ? clean : `${clean.slice(0, maxLength - 1).trimEnd()}…`;
}

function collectConversationNavigatorItems() {
  const conv = store.activeConversation;
  if (!conv) return [];
  return (conv.messages || [])
    .map((message, messageIndex) => ({ message, messageIndex }))
    .filter(({ message }) => message.role === 'user' && String(message.content || '').trim())
    .map(({ message, messageIndex }, turnIndex) => ({
      id: message.id,
      messageIndex,
      turnIndex,
      text: conversationNavigatorSnippet(message.content),
    }));
}

function conversationNavigatorMarkerTop(item, fallbackIndex = 0, total = 1) {
  const row = els.messages.querySelector(`[data-message-id="${CSS.escape(item.id)}"]`);
  if (row) {
    const max = Math.max(1, els.scroller.scrollHeight - row.offsetHeight);
    return Math.max(1, Math.min(99, (row.offsetTop / max) * 100));
  }
  return total <= 1 ? 50 : Math.max(1, Math.min(99, (fallbackIndex / (total - 1)) * 100));
}

function conversationNavigatorCurrentIndex() {
  if (!conversationNavItems.length) return -1;
  const anchor = els.scroller.scrollTop + Math.min(els.scroller.clientHeight * 0.34, 280);
  let best = 0;
  for (let i = 0; i < conversationNavItems.length; i += 1) {
    const row = els.messages.querySelector(`[data-message-id="${CSS.escape(conversationNavItems[i].id)}"]`);
    if (!row) continue;
    if (row.offsetTop <= anchor) best = i;
    else break;
  }
  return best;
}

function syncConversationNavigatorActive({ scrollList = false } = {}) {
  if (!conversationNavItems.length) return;
  const next = conversationNavigatorCurrentIndex();
  if (next < 0) return;
  conversationNavActiveIndex = next;
  els.conversationNavigatorRail.querySelectorAll('[data-conversation-nav-marker]').forEach((button, index) => {
    button.classList.toggle('active', index === next);
  });
  els.conversationNavigatorList.querySelectorAll('[data-conversation-nav-item]').forEach((button, index) => {
    button.classList.toggle('active', index === next);
  });
  if (scrollList && conversationNavOpen) {
    els.conversationNavigatorList.querySelector(`[data-conversation-nav-item="${next}"]`)?.scrollIntoView({ block: 'nearest' });
  }
}

function renderConversationNavigator() {
  conversationNavItems = collectConversationNavigatorItems();
  const count = conversationNavItems.length;
  const shouldShow = count > 1;
  els.conversationNavigatorRail.classList.toggle('hidden', !shouldShow);
  if (!shouldShow) {
    setConversationNavigator(false);
    els.conversationNavigatorRail.innerHTML = '';
    els.conversationNavigatorList.innerHTML = '';
    conversationNavActiveIndex = count ? 0 : -1;
    return;
  }

  conversationNavActiveIndex = conversationNavigatorCurrentIndex();
  els.conversationNavigatorRail.innerHTML = conversationNavItems.map((item, index) => (
    `<button type="button" class="conversation-navigator-marker ${index === conversationNavActiveIndex ? 'active' : ''}" style="top:${conversationNavigatorMarkerTop(item, index, count).toFixed(2)}%" data-conversation-nav-marker="${index}" tabindex="-1" aria-label="Jump to turn ${index + 1}"></button>`
  )).join('');

  els.conversationNavigatorList.innerHTML = conversationNavItems.map((item, index) => (
    `<button type="button" class="conversation-navigator-item ${index === conversationNavActiveIndex ? 'active' : ''}" data-conversation-nav-item="${index}" title="${escapeHtml(item.text)}">${escapeHtml(item.text)}</button>`
  )).join('');

  els.conversationNavigatorRail.querySelectorAll('[data-conversation-nav-marker]').forEach((button) => {
    button.onmouseenter = () => {
      clearTimeout(conversationNavCloseTimer);
      const index = Number(button.dataset.conversationNavMarker);
      if (Number.isFinite(index)) {
        conversationNavActiveIndex = index;
        setConversationNavigator(true, { scrollList: true });
      }
    };
    button.onclick = () => { setConversationNavigator(true, { scrollList: true }); goToConversationNavigatorItem(Number(button.dataset.conversationNavMarker)); };
  });
  els.conversationNavigatorList.querySelectorAll('[data-conversation-nav-item]').forEach((button) => {
    button.onclick = () => goToConversationNavigatorItem(Number(button.dataset.conversationNavItem));
  });
  syncConversationNavigatorActive({ scrollList: conversationNavOpen });
}

function queueConversationNavigatorRefresh() {
  if (conversationNavRefreshFrame) return;
  conversationNavRefreshFrame = requestAnimationFrame(() => {
    conversationNavRefreshFrame = 0;
    renderConversationNavigator();
  });
}

function setConversationNavigator(open, { scrollList = true } = {}) {
  conversationNavOpen = !!open && conversationNavItems.length > 1;
  clearTimeout(conversationNavCloseTimer);
  els.conversationNavigatorPanel.classList.toggle('hidden', !conversationNavOpen);
  els.conversationNavigatorPanel.setAttribute('aria-hidden', conversationNavOpen ? 'false' : 'true');
  els.conversationNavigatorRail.classList.toggle('panel-open', conversationNavOpen);
  if (conversationNavOpen && scrollList) {
    requestAnimationFrame(() => {
      els.conversationNavigatorList.querySelector(`[data-conversation-nav-item="${conversationNavActiveIndex}"]`)?.scrollIntoView({ block: 'nearest' });
    });
  }
}

function scheduleConversationNavigatorClose() {
  clearTimeout(conversationNavCloseTimer);
  conversationNavCloseTimer = setTimeout(() => setConversationNavigator(false), 260);
}

function openConversationNavigator() {
  if (conversationNavItems.length <= 1) renderConversationNavigator();
  if (conversationNavItems.length <= 1) return toast('Add another turn to use the conversation navigator.', 'info');
  syncConversationNavigatorActive();
  setConversationNavigator(true, { scrollList: true });
}

function goToConversationNavigatorItem(index, { smooth = true } = {}) {
  if (!conversationNavItems.length) return;
  const total = conversationNavItems.length;
  conversationNavActiveIndex = ((Number(index) || 0) % total + total) % total;
  const item = conversationNavItems[conversationNavActiveIndex];
  const row = els.messages.querySelector(`[data-message-id="${CSS.escape(item.id)}"]`);
  if (row) row.scrollIntoView({ block: 'center', behavior: smooth ? 'smooth' : 'auto' });
  els.conversationNavigatorRail.querySelectorAll('[data-conversation-nav-marker]').forEach((button, i) => button.classList.toggle('active', i === conversationNavActiveIndex));
  els.conversationNavigatorList.querySelectorAll('[data-conversation-nav-item]').forEach((button, i) => button.classList.toggle('active', i === conversationNavActiveIndex));
  els.conversationNavigatorList.querySelector(`[data-conversation-nav-item="${conversationNavActiveIndex}"]`)?.scrollIntoView({ block: 'nearest' });
}

function artifactPayloadBytes(item) {
  if (!item) return 0;
  if (item.type === 'bundle') return (item.files || []).reduce((sum, file) => sum + new Blob([String(file.content || '')]).size, 0);
  return new Blob([String(item.content || '')]).size;
}

function artifactDownloadMeta(item) {
  if (!item) return '';
  if (item.type === 'bundle') return `ZIP · ${(item.files || []).length} file${(item.files || []).length === 1 ? '' : 's'} · ${humanBytes(artifactPayloadBytes(item))}`;
  const ext = String(item.filename || '').split('.').pop()?.toUpperCase() || item.type.toUpperCase();
  return `${ext} · ${humanBytes(artifactPayloadBytes(item))}`;
}

function downloadArtifactItem(item) {
  if (!item) return;
  let blob;
  let filename;
  if (item.type === 'bundle') {
    blob = createZipBlob(item.files || []);
    const base = normalizeDownloadName(String(item.filename || item.title || 'artifact').replace(/\.zip$/i, ''));
    filename = `${base}.zip`;
  } else if (item.type === 'file') {
    blob = new Blob([String(item.content || '')], { type: item.mime || 'application/octet-stream' });
    filename = normalizeDownloadName((item.filename || `${item.title || 'artifact'}.txt`).replaceAll('/', '-'));
  } else {
    const ext = item.type === 'html' ? 'html' : item.language || (item.type === 'markdown' ? 'md' : 'txt');
    blob = new Blob([item.content], { type: item.type === 'html' ? 'text/html' : 'text/plain' });
    filename = `${normalizeDownloadName(item.title)}.${ext}`;
  }
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 1200);
}

function messageArtifactCardsHtml(message) {
  const ids = Array.isArray(message?.artifactIds) ? [...new Set(message.artifactIds)] : [];
  const items = ids.map((id) => artifacts.get(id)).filter((item) => item && (item.type === 'file' || item.type === 'bundle'));
  if (!items.length) return '';
  return `<div class="message-file-artifacts">${items.map((item) => `
    <button type="button" class="message-file-card" data-download-message-artifact="${escapeHtml(item.id)}" title="Download ${escapeHtml(item.filename || item.title)}">
      <span class="message-file-icon">${item.type === 'bundle' ? 'ZIP' : icon('file', 17)}</span>
      <span class="message-file-copy"><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(artifactDownloadMeta(item))}</small></span>
      <span class="message-file-download">${icon('download', 16)}</span>
    </button>`).join('')}</div>`;
}

function bindMessageArtifactDownloads(root = document) {
  root.querySelectorAll?.('[data-download-message-artifact]').forEach((button) => {
    if (button.dataset.downloadBound === '1') return;
    button.dataset.downloadBound = '1';
    button.onclick = () => downloadArtifactItem(artifacts.get(button.dataset.downloadMessageArtifact));
  });
}

function messageActionsHtml(message) {
  if (message.live) return '';
  if (message.role === 'user') {
    return `<div class="message-actions user-actions" aria-label="Message actions">
      <button type="button" data-message-action="copy" data-message-target="${message.id}" title="Copy" aria-label="Copy message">${icon('copy', 15)}</button>
      <button type="button" data-message-action="edit" data-message-target="${message.id}" title="Edit" aria-label="Edit message">${icon('edit', 15)}</button>
      <button type="button" data-message-action="delete" data-message-target="${message.id}" title="Delete" aria-label="Delete message">${icon('trash', 15)}</button>
    </div>`;
  }
  return `<div class="message-actions assistant-actions" aria-label="Response actions">
    <button type="button" data-message-action="copy" data-message-target="${message.id}" title="Copy" aria-label="Copy response">${icon('copy', 15)}</button>
    <button type="button" data-message-action="regenerate" data-message-target="${message.id}" title="Regenerate" aria-label="Regenerate response">${icon('refresh', 15)}</button>
    <button type="button" data-message-action="delete" data-message-target="${message.id}" title="Delete" aria-label="Delete response">${icon('trash', 15)}</button>
  </div>`;
}

function findActiveMessage(messageId) {
  const conv = store.activeConversation;
  const index = conv?.messages.findIndex((m) => m.id === messageId) ?? -1;
  return { conv, index, message: index >= 0 ? conv.messages[index] : null };
}

async function copyMessage(messageId) {
  const { message } = findActiveMessage(messageId);
  if (!message) return;
  try {
    await navigator.clipboard.writeText(String(message.content || ''));
    toast('Copied.', 'success');
  } catch {
    toast('Could not copy this message.', 'error');
  }
}

function editUserMessage(messageId) {
  if (generating) return toast('Stop the current generation before editing a message.', 'info');
  const { message } = findActiveMessage(messageId);
  if (!message || message.role !== 'user') return;
  const text = String(message.content || '');
  const hadAttachment = !!message.attachmentName;
  store.truncateFromMessage(messageId);
  els.promptInput.value = text;
  autoResizeComposer();
  renderConversation();
  els.promptInput.focus();
  els.promptInput.setSelectionRange?.(text.length, text.length);
  if (hadAttachment) toast('Message moved back to the composer. Reattach the original file if needed.', 'info');
}

function openDeleteMessage(messageId) {
  if (generating) return toast('Stop the current generation before deleting a message.', 'info');
  const { message } = findActiveMessage(messageId);
  if (!message) return;
  const isUser = message.role === 'user';
  modalShell(isUser ? 'Delete message and response?' : 'Delete response?', `
    <div class="confirm-dialog">
      <p>${isUser ? 'This user message and its following response will be removed from the conversation.' : 'This response will be removed from the conversation.'}</p>
      <div class="modal-actions">
        <button class="secondary-button" type="button" id="deleteMessageCancel">Cancel</button>
        <button class="danger-button" type="button" id="deleteMessageConfirm">Delete</button>
      </div>
    </div>`);
  document.getElementById('deleteMessageCancel').onclick = closeModal;
  document.getElementById('deleteMessageConfirm').onclick = () => {
    store.deleteMessage(messageId, { withResponse: isUser });
    reasoningUiState.delete(messageId);
    closeModal();
    renderConversation();
    toast('Message deleted.', 'success');
  };
}

function regenerateAssistant(messageId) {
  if (generating) return toast('A generation is already running.', 'info');
  const { conv, index, message } = findActiveMessage(messageId);
  if (!conv || !message || message.role !== 'assistant' || index < 1) return;
  let userIndex = index - 1;
  while (userIndex >= 0 && conv.messages[userIndex]?.role !== 'user') userIndex -= 1;
  const user = conv.messages[userIndex];
  if (!user) return toast('Could not find the user message for this response.', 'error');
  if (user.attachmentName) return toast('Reattach the original file before regenerating this response.', 'info');
  const text = String(user.content || '');
  store.truncateFromMessage(user.id);
  els.promptInput.value = text;
  autoResizeComposer();
  renderConversation();
  sendPrompt();
}

function bindMessageActions(root = document) {
  root.querySelectorAll?.('[data-message-action]').forEach((button) => {
    if (button.dataset.messageActionBound === '1') return;
    button.dataset.messageActionBound = '1';
    button.onclick = (event) => {
      event.stopPropagation();
      const id = button.dataset.messageTarget;
      const action = button.dataset.messageAction;
      if (action === 'copy') copyMessage(id);
      else if (action === 'edit') editUserMessage(id);
      else if (action === 'regenerate') regenerateAssistant(id);
      else if (action === 'delete') openDeleteMessage(id);
    };
  });
}

function renderConversation() {
  const conv = store.activeConversation;
  const messages = conv?.messages || [];
  els.messages.innerHTML = messages.map((m) => {
    if (m.role === 'user') {
      return `<article class="message-row user-row" data-message-id="${m.id}">
        <div class="user-message-wrap">
          <div class="user-bubble">${escapeHtml(m.content || '')}${m.attachmentName ? `<div class="attached-name">${icon('clip', 14)} ${escapeHtml(m.attachmentName)}</div>` : ''}</div>
          ${messageActionsHtml(m)}
        </div>
      </article>`;
    }
    const activity = activityHtml(m);
    const reasoning = reasoningHtml(m, { streaming: !!m.live });
    const tools = renderToolEvents(m.tools || []);
    return `<article class="message-row assistant-row ${m.live ? 'live-message' : ''}" data-message-id="${m.id}">
      <img src="/blackriver-mark.svg" alt="" class="assistant-mark" />
      <div class="assistant-content"><div class="activity-slot">${activity}</div><div class="reasoning-slot">${reasoning}</div><div class="tools-slot">${tools}</div><div class="markdown ${m.live ? 'streaming' : ''}">${renderMarkdown(m.content || '', { streaming: !!m.live })}</div><div class="message-artifacts-slot">${messageArtifactCardsHtml(m)}</div>${messageActionsHtml(m)}</div>
    </article>`;
  }).join('');
  renderEmptyState();
  requestAnimationFrame(() => scrollConversation({ force: true }));
  bindCopyButtons();
  bindMessageActions(els.messages);
  bindMessageArtifactDownloads(els.messages);
  bindReasoningInteractions(els.messages);
  queueConversationNavigatorRefresh();
}

function bindCopyButtons() {
  document.querySelectorAll('[data-copy-code]').forEach((btn) => {
    btn.onclick = async () => {
      const code = btn.closest('.code-block')?.querySelector('code')?.textContent || '';
      await navigator.clipboard?.writeText(code);
      btn.textContent = 'Copied';
      setTimeout(() => btn.textContent = 'Copy', 900);
    };
  });
}

function updateAssistantDom(message, { streaming = false, conversationId = null } = {}) {
  // A generation may keep running while the user browses another Chat/Work.
  // Never let background stream updates rebuild or scroll the conversation that
  // is currently on screen. The message object still updates in the store and
  // will render at its latest state when the user returns to that conversation.
  if (conversationId && store.state.activeConversationId !== conversationId) return;
  const row = document.querySelector(`[data-message-id="${CSS.escape(message.id)}"]`);
  if (!row) return renderConversation();
  const follow = isNearBottom();

  const activitySlot = row.querySelector('.activity-slot');
  const toolsSlot = row.querySelector('.tools-slot');
  const markdown = row.querySelector('.markdown');
  const artifactsSlot = row.querySelector('.message-artifacts-slot');
  if (!markdown) return renderConversation();

  row.classList.toggle('live-message', !!message.live);
  if (activitySlot) activitySlot.innerHTML = activityHtml(message);
  updateReasoningDom(row, message, { streaming });
  if (toolsSlot) toolsSlot.innerHTML = renderToolEvents(message.tools || []);

  // Incremental Markdown, not a raw text dump. Incomplete fenced code blocks are
  // virtually closed for rendering so the stream stays formatted while tokens arrive.
  markdown.classList.toggle('streaming', streaming);
  markdown.innerHTML = renderMarkdown(message.content || '', { streaming });
  if (artifactsSlot) {
    artifactsSlot.innerHTML = messageArtifactCardsHtml(message);
    // A downloadable artifact can complete before the assistant's final text.
    // Bind the card immediately so the user can download it while the response
    // is still streaming instead of waiting for the whole turn to finish.
    bindMessageArtifactDownloads(artifactsSlot);
  }

  let actions = row.querySelector('.message-actions');
  if (!message.live && !actions) {
    row.querySelector('.assistant-content')?.insertAdjacentHTML('beforeend', messageActionsHtml(message));
    actions = row.querySelector('.message-actions');
  }
  if (message.live && actions) actions.remove();

  if (!streaming) {
    bindCopyButtons();
    bindMessageActions(row);
    bindMessageArtifactDownloads(row);
  }
  queueConversationNavigatorRefresh();
  if (follow) requestAnimationFrame(() => scrollConversation());
}

function queueAssistantDomUpdate(message, conversationId = generationConversationId) {
  if (conversationId && store.state.activeConversationId !== conversationId) return;
  if (streamFrames.has(message.id)) return;
  streamFrames.set(message.id, requestAnimationFrame(() => {
    streamFrames.delete(message.id);
    if (conversationId && store.state.activeConversationId !== conversationId) return;
    updateAssistantDom(message, { streaming: generating, conversationId });
  }));
}

function refreshRuntimeUi(detail = null) {
  const hardware = runtime.hardware;
  if (runtime.isLoaded) {
    els.modelName.textContent = runtime.loaded?.name || 'Loaded model';
    els.runtimeText.textContent = runtime.backendLabel;
    els.runtimeChip.classList.toggle('warning', runtime.isLocal && !hardware.adapter);
  } else {
    els.modelName.textContent = 'Choose model';
    els.runtimeText.textContent = runtime.isApi ? (runtime.backendLabel || 'API') : (hardware.checked ? (hardware.adapter ? 'Local · WebGPU' : 'Local') : 'Local');
    els.runtimeChip.classList.remove('warning');
  }
  if (detail?.state === 'downloading') {
    els.composerCaption.textContent = detail.message || 'Downloading model…';
  } else if (detail?.state === 'loading') {
    els.composerCaption.textContent = detail.message || 'Loading model…';
  } else if (!generating) {
    updateInferenceCaption(lastInferenceMetrics);
  }
  syncContextUi();
}

function autoResizeComposer() {
  els.promptInput.style.height = 'auto';
  els.promptInput.style.height = `${Math.min(180, Math.max(28, els.promptInput.scrollHeight))}px`;
}

function setAttachment(file) {
  pendingAttachment = file || null;
  if (!file) {
    els.attachmentPreview.classList.add('hidden');
    els.attachmentPreview.innerHTML = '';
    return;
  }
  els.attachmentPreview.classList.remove('hidden');
  els.attachmentPreview.innerHTML = `<span>${icon('clip', 15)}<strong>${escapeHtml(file.name)}</strong><small>${humanBytes(file.size)}</small></span><button id="removeAttachment">${icon('x', 15)}</button>`;
  document.getElementById('removeAttachment').onclick = () => setAttachment(null);
}

function normalizeArtifactStorageSnapshot(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const out = {};
  let bytes = 0;
  let count = 0;
  for (const [rawKey, rawValue] of Object.entries(value)) {
    if (count >= 128) break;
    const key = String(rawKey).slice(0, 512);
    const entry = String(rawValue).slice(0, 32_768);
    const cost = key.length + entry.length;
    if (bytes + cost > 128 * 1024) break;
    out[key] = entry;
    bytes += cost;
    count += 1;
  }
  return out;
}

function readArtifactLocalStorage(artifactId) {
  try {
    return normalizeArtifactStorageSnapshot(JSON.parse(localStorage.getItem(`${ARTIFACT_STORAGE_PREFIX}${artifactId}`) || '{}'));
  } catch {
    return {};
  }
}

function writeArtifactLocalStorage(artifactId, snapshot) {
  try {
    localStorage.setItem(`${ARTIFACT_STORAGE_PREFIX}${artifactId}`, JSON.stringify(normalizeArtifactStorageSnapshot(snapshot)));
  } catch {
    // Preview storage is best-effort. The artifact must still remain runnable if
    // browser storage is unavailable or full.
  }
}

function inlineScriptJson(value) {
  return JSON.stringify(value)
    .replaceAll('<', '\\u003c')
    .replaceAll('>', '\\u003e')
    .replaceAll('&', '\\u0026')
    .replace(/\u2028/g, '\\u2028')
    .replace(/\u2029/g, '\\u2029');
}

function artifactPreviewBootstrap(item) {
  const localSeed = readArtifactLocalStorage(item.id);
  const sessionSeed = normalizeArtifactStorageSnapshot(artifactSessionStorage.get(item.id) || {});
  const config = inlineScriptJson({
    bridge: ARTIFACT_PREVIEW_BRIDGE,
    artifactId: item.id,
    localSeed,
    sessionSeed,
  });

  return `<script data-blackriver-preview-bootstrap>\n(() => {\n  'use strict';\n  const cfg = ${config};\n  const send = (type, detail = {}) => {\n    try { parent.postMessage({ bridge: cfg.bridge, artifactId: cfg.artifactId, type, ...detail }, '*'); } catch {}\n  };\n  const makeStorage = (seed, area) => {\n    const data = new Map(Object.entries(seed || {}).map(([k, v]) => [String(k), String(v)]));\n    const sync = () => send('storage', { area, snapshot: Object.fromEntries(data) });\n    return {\n      get length() { return data.size; },\n      key(index) { return Array.from(data.keys())[Number(index)] ?? null; },\n      getItem(key) { key = String(key); return data.has(key) ? data.get(key) : null; },\n      setItem(key, value) { data.set(String(key), String(value)); sync(); },\n      removeItem(key) { data.delete(String(key)); sync(); },\n      clear() { data.clear(); sync(); },\n    };\n  };\n  const local = makeStorage(cfg.localSeed, 'local');\n  const session = makeStorage(cfg.sessionSeed, 'session');\n  window.__blackriverLocalStorage = local;\n  window.__blackriverSessionStorage = session;\n  // Sandboxed srcdoc documents intentionally have an opaque origin. Native\n  // localStorage/sessionStorage therefore throw SecurityError. Replace only the\n  // storage surfaces with isolated, artifact-scoped shims instead of granting\n  // allow-same-origin (which would expose the Workspace origin to artifact code).\n  try { Object.defineProperty(window, 'localStorage', { configurable: true, enumerable: true, value: local }); } catch {}\n  try { Object.defineProperty(window, 'sessionStorage', { configurable: true, enumerable: true, value: session }); } catch {}\n\n  window.addEventListener('error', (event) => {\n    send('runtime-error', { message: String(event?.message || 'Artifact script error').slice(0, 500) });\n  });\n  window.addEventListener('unhandledrejection', (event) => {\n    const reason = event?.reason?.message || event?.reason || 'Unhandled promise rejection';\n    send('runtime-error', { message: String(reason).slice(0, 500) });\n  });\n  window.addEventListener('message', (event) => {\n    if (event?.data?.bridge !== cfg.bridge || event.data.type !== 'host-resize') return;\n    requestAnimationFrame(() => window.dispatchEvent(new Event('resize')));\n  });\n  send('bootstrap-ready');\n})();\n<\/script>`;
}

function artifactPreviewDocument(item) {
  if (item.type !== 'html') {
    return `<html><body style="margin:0;background:#fff;color:#111;font:16px/1.5 system-ui;padding:32px;white-space:pre-wrap">${escapeHtml(item.content)}</body></html>`;
  }

  const bootstrap = artifactPreviewBootstrap(item);
  const html = String(item.content || '');
  const headOpen = html.match(/<head(?:\s[^>]*)?>/i);
  if (headOpen?.index != null) {
    const insertion = headOpen.index + headOpen[0].length;
    return `${html.slice(0, insertion)}${bootstrap}${html.slice(insertion)}`;
  }
  const htmlOpen = html.match(/<html(?:\s[^>]*)?>/i);
  if (htmlOpen?.index != null) {
    const insertion = htmlOpen.index + htmlOpen[0].length;
    return `${html.slice(0, insertion)}<head>${bootstrap}</head>${html.slice(insertion)}`;
  }
  return `<!doctype html><html><head>${bootstrap}</head><body>${html}</body></html>`;
}

function clearArtifactPreviewError() {
  els.artifactPreviewError?.classList.add('hidden');
  if (els.artifactPreviewErrorText) els.artifactPreviewErrorText.textContent = '';
}

function showArtifactPreviewError(message) {
  if (!els.artifactPreviewError || artifactViewMode !== 'preview') return;
  els.artifactPreviewErrorText.textContent = String(message || 'Artifact script error');
  els.artifactPreviewError.classList.remove('hidden');
}

function notifyArtifactPreviewResize() {
  if (!els.artifactFrame?.contentWindow || els.artifactFrame.classList.contains('hidden')) return;
  cancelAnimationFrame(artifactPreviewResizeFrame);
  artifactPreviewResizeFrame = requestAnimationFrame(() => {
    artifactPreviewResizeFrame = 0;
    try {
      els.artifactFrame.contentWindow.postMessage({ bridge: ARTIFACT_PREVIEW_BRIDGE, type: 'host-resize' }, '*');
    } catch {}
  });
}

function handleArtifactPreviewBridge(event) {
  if (event.source !== els.artifactFrame?.contentWindow) return;
  const data = event.data;
  if (!data || data.bridge !== ARTIFACT_PREVIEW_BRIDGE || typeof data.artifactId !== 'string') return;
  const active = artifacts.get(artifacts.activeId);
  if (!active || data.artifactId !== active.id) return;

  if (data.type === 'storage') {
    const snapshot = normalizeArtifactStorageSnapshot(data.snapshot);
    if (data.area === 'local') writeArtifactLocalStorage(active.id, snapshot);
    if (data.area === 'session') artifactSessionStorage.set(active.id, snapshot);
    return;
  }
  if (data.type === 'runtime-error') {
    showArtifactPreviewError(data.message);
    return;
  }
  if (data.type === 'bootstrap-ready') {
    notifyArtifactPreviewResize();
  }
}

function scheduleArtifactPreview(item, { force = false } = {}) {
  if (!item || !els.artifactFrame) return;
  const signature = `${item.id}:${item.updatedAt}:${item.content.length}`;
  if (!force && artifactPreviewSignature === signature && els.artifactFrame.srcdoc) {
    els.artifactPreviewLoading?.classList.add('hidden');
    notifyArtifactPreviewResize();
    return;
  }

  const renderToken = ++artifactPreviewRenderToken;
  artifactPreviewSignature = signature;
  clearArtifactPreviewError();
  els.artifactPreviewLoading?.classList.remove('hidden');

  // The artifact pane changes the Work grid from one column to two. Loading an
  // iframe in the very same frame can give responsive/canvas artifacts a zero or
  // stale viewport on Chromium. Wait until the split layout has committed before
  // creating the srcdoc document; the preview bridge then fires a second resize
  // once the sandboxed document itself is ready.
  requestAnimationFrame(() => {
    if (renderToken !== artifactPreviewRenderToken) return;
    els.artifactPane.getBoundingClientRect();
    requestAnimationFrame(() => {
      if (renderToken !== artifactPreviewRenderToken) return;
      els.artifactFrame.srcdoc = artifactPreviewDocument(item);
    });
  });
}

function renderArtifact(item = artifacts.get(artifacts.activeId), { force = false } = {}) {
  const activeConv = store.activeConversation;
  if (item && !['html', 'code', 'text', 'markdown'].includes(item.type)) {
    syncArtifactReopenButton();
    return;
  }
  if (!item || store.state.mode !== 'work' || item.conversationId !== activeConv?.id) {
    hideArtifactPane({ preserveActive: true });
    syncArtifactReopenButton();
    return;
  }
  if (!force && artifactDismissedConversations.has(activeConv.id)) {
    hideArtifactPane({ preserveActive: true });
    syncArtifactReopenButton();
    return;
  }
  if (force) artifactDismissedConversations.delete(activeConv.id);
  // Keep the UI-selected artifact explicit. ArtifactStore.activeId can change as
  // background Work creates artifacts in another conversation; the viewer that
  // is already on screen must keep pointing at the item the user is looking at.
  displayedArtifactId = item.id;
  artifacts.activeId = item.id;
  els.artifactPane.classList.remove('hidden');
  els.workbench.classList.add('artifact-open');
  els.artifactResizeHandle.classList.toggle('hidden', artifactFullscreen || window.matchMedia('(max-width: 900px)').matches);
  syncArtifactSplit();
  els.artifactTitle.textContent = item.title;
  syncArtifactPicker(item);
  const allArtifacts = activeConversationArtifacts();
  const artifactIndex = Math.max(0, allArtifacts.findIndex((entry) => entry.id === item.id));
  const position = allArtifacts.length > 1 ? `Artifact ${artifactIndex + 1}/${allArtifacts.length} · ` : '';
  els.artifactMeta.textContent = `${position}${item.type.toUpperCase()}${item.language ? ` · ${item.language}` : ''} · ${humanBytes(new Blob([item.content]).size)}`;
  els.artifactCode.querySelector('code').textContent = item.content;
  setArtifactView(artifactViewMode, { item, forcePreview: force });
  syncArtifactReopenButton();
}

