  modalShell('Library', `<div class="library-grid">${list.length ? list.map((a) => `<button class="library-item" data-artifact-id="${a.id}"><span class="library-icon">${icon('file', 20)}</span><span><strong>${escapeHtml(a.title)}</strong><small>${a.type.toUpperCase()} · ${formatDate(a.updatedAt)}</small></span></button>`).join('') : '<div class="empty-panel">Artifacts and downloadable files you create appear here.</div>'}</div>`);
