function diffText(before = '', after = '') {
  const a = String(before ?? '').split(/\r?\n/);
  const b = String(after ?? '').split(/\r?\n/);
  const cap = 260;
  if (a.length > cap || b.length > cap) {
    return `--- before\n${a.slice(0, 120).map((line) => `- ${line}`).join('\n')}\n…\n+++ after\n${b.slice(0, 120).map((line) => `+ ${line}`).join('\n')}\n…`;
  }
  const dp = Array.from({ length: a.length + 1 }, () => new Uint16Array(b.length + 1));
  for (let i = a.length - 1; i >= 0; i--) for (let j = b.length - 1; j >= 0; j--) dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  const out = ['--- before', '+++ after'];
  let i = 0, j = 0;
  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length && a[i] === b[j]) { out.push(`  ${a[i]}`); i++; j++; }
    else if (j < b.length && (i >= a.length || dp[i][j + 1] >= dp[i + 1][j])) { out.push(`+ ${b[j++]}`); }
    else if (i < a.length) { out.push(`- ${a[i++]}`); }
  }
  return out.join('\n');
}

function diffMarkup(before = '', after = '') {
  return diffText(before, after).split('\n').map((line) => {
    const cls = line.startsWith('+++') || line.startsWith('---') ? 'header' : line.startsWith('+ ') ? 'add' : line.startsWith('- ') ? 'del' : 'same';
    return `<span class="diff-line ${cls}">${escapeHtml(line)}</span>`;
  }).join('');
}

function renderProjectChange(projectId, path) {
  const record = project.projects.find((item) => item.id === projectId);
  const change = record?.changedFiles?.find((item) => item.path === path);
  if (!change) return toast('Tracked change no longer exists.', 'info');
  modalShell(`Changed · ${path}`, `<div class="change-diff-head"><span class="status-pill ${change.status}">${escapeHtml(change.status)}</span><small>Tracked by BlackRiver Work</small></div><pre class="project-diff"><code>${diffMarkup(change.before ?? '', change.after ?? '')}</code></pre><div class="modal-actions"><button class="secondary-button" id="backToProjects">Back</button>${project.id === projectId ? '<button class="secondary-button danger-soft" id="revertTrackedChange">Revert file</button>' : ''}</div>`, { wide: true });
  document.getElementById('backToProjects').onclick = renderProjectsModal;
  const revert = document.getElementById('revertTrackedChange');
  if (revert) revert.onclick = async () => {
    try { await project.revertChange(path); toast(`Reverted ${path}`, 'success'); renderProjectsModal(); }
    catch (error) { toast(errorMessage(error), 'error'); }
  };
}

function renderProjectsModal() {
  const projects = project.projects;
  const active = project.activeProject;
  const projectCards = projects.length ? projects.map((item) => {
    const selected = item.id === project.id;
    const changed = item.changedFiles?.length || 0;
    const conversations = store.state.conversations.filter((c) => c.mode === 'work' && (c.projectId || null) === item.id).length;
    const artifactCount = artifacts.list(null, item.id).length;
    return `<div class="project-card project-card-v2 ${selected ? 'active' : ''}">
      <div class="feature-icon">${icon('folder', 22)}</div>
      <div class="project-card-copy"><strong>${escapeHtml(item.name)}</strong><p>${conversations} conversation${conversations === 1 ? '' : 's'} · ${artifactCount} artifact${artifactCount === 1 ? '' : 's'}${changed ? ` · ${changed} changed` : ''}</p></div>
      <div class="project-card-actions"><button class="secondary-button" data-project-open="${item.id}">${selected && project.root ? 'Active' : (selected ? 'Reconnect' : 'Open')}</button><button class="icon-button project-remove" data-project-remove="${item.id}" title="Forget project" aria-label="Forget project">${icon('x', 15)}</button></div>
    </div>`;
  }).join('') : '<div class="empty-panel">No projects yet. Add a local folder and BlackRiver will remember it here.</div>';

  const changedMarkup = active?.changedFiles?.length ? active.changedFiles.map((change) => `<div class="changed-file-row"><span class="change-code ${change.status}">${change.status === 'added' ? 'A' : change.status === 'deleted' ? 'D' : 'M'}</span><button data-change-view="${escapeHtml(change.path)}" title="View diff">${escapeHtml(change.path)}</button><small>${formatDate(change.updatedAt)}</small></div>`).join('') : '<div class="project-empty-inline">No tracked Work changes in this project.</div>';
  const recentMarkup = active?.recentFiles?.length ? active.recentFiles.slice(0, 10).map((path) => `<span class="recent-file-chip">${escapeHtml(path)}</span>`).join('') : '<span class="project-muted">Files read or edited by Work will appear here.</span>';
  const indexedFiles = active?.fileIndex?.filter((entry) => entry.kind === 'file') || [];
  const projectFilesMarkup = indexedFiles.length ? indexedFiles.slice(0, 24).map((entry) => `<span class="recent-file-chip project-index-file">${escapeHtml(entry.path)}</span>`).join('') : `<span class="project-muted">${project.root ? 'No files found in the latest scan.' : 'Reconnect the project to scan its files.'}</span>`;

  modalShell('Projects', `<div class="projects-toolbar"><div><strong>Projects</strong><small>Persistent, isolated Work contexts</small></div><button class="primary-button" id="projectAdd">${icon('folder', 15)} Add project</button></div>
    <div class="project-list-v2">${projectCards}</div>
    ${active ? `<div class="project-detail-v2">
      <div class="project-detail-head"><div><strong>${escapeHtml(active.name)}</strong><small>${project.root ? 'Filesystem connected' : 'Saved · permission required'} · ${project.store.persistence === 'indexeddb' ? 'Persistent' : 'Session only'}</small></div><span class="status-pill ${project.root ? 'connected' : 'prompt'}">${project.root ? 'Connected' : 'Reconnect'}</span></div>
      <label class="project-field"><span>Project instructions</span><textarea id="projectInstructions" placeholder="Rules Work should always follow in this project…">${escapeHtml(active.instructions || '')}</textarea></label>
      <label class="project-field"><span>Pinned context <small>one item per line</small></span><textarea id="projectPinned" placeholder="Architecture decisions, important files, constraints…">${escapeHtml((active.pinnedContext || []).join('\n'))}</textarea></label>
      <div class="project-detail-actions"><button class="secondary-button" id="saveProjectContext">Save project context</button></div>
      <div class="project-subsection"><div class="project-subhead"><strong>Project files</strong><span>${indexedFiles.length} indexed</span></div><div class="project-index-actions"><div class="recent-file-list">${projectFilesMarkup}</div>${project.root ? '<button class="secondary-button project-refresh-index" id="refreshProjectFiles">Refresh</button>' : ''}</div></div>
      <div class="project-subsection"><div class="project-subhead"><strong>Recently touched</strong></div><div class="recent-file-list">${recentMarkup}</div></div>
      <div class="project-subsection"><div class="project-subhead"><strong>Changed Files</strong><span>${active.changedFiles?.length || 0}</span></div><div class="changed-files-list">${changedMarkup}</div></div>
    </div>` : ''}`, { wide: true });

  document.getElementById('projectAdd').onclick = async () => {
    try { await chooseProject({ keepModal: true }); renderProjectsModal(); } catch (e) { if (e.name !== 'AbortError') toast(errorMessage(e), 'error'); }
  };
  document.querySelectorAll('[data-project-open]').forEach((button) => button.onclick = async () => {
    try { await activateProject(button.dataset.projectOpen); renderProjectsModal(); } catch (error) { toast(errorMessage(error), 'error'); }
  });
  document.querySelectorAll('[data-project-remove]').forEach((button) => button.onclick = async () => {
    const item = project.projects.find((p) => p.id === button.dataset.projectRemove);
    if (!item || !window.confirm(`Forget “${item.name}” from BlackRiver Projects? Files on disk are not deleted.`)) return;
    store.detachProject(item.id);
    artifacts.detachProject(item.id);
    await project.removeProject(item.id);
    store.setActiveProject(project.id || null);
    renderAll();
    renderProjectsModal();
  });
  document.getElementById('saveProjectContext')?.addEventListener('click', async () => {
    await project.updateProject({ instructions: document.getElementById('projectInstructions').value, pinnedContext: document.getElementById('projectPinned').value.split(/\r?\n/) });
    toast('Project context saved', 'success');
    renderProjectsModal();
  });
  document.getElementById('refreshProjectFiles')?.addEventListener('click', async () => {
    try {
      await project.refreshFileIndex(project.id, { root: project.root, maxDepth: 4, maxEntries: 250 });
      toast('Project files refreshed', 'success');
      renderProjectsModal();
    } catch (error) { toast(errorMessage(error), 'error'); }
  });
  document.querySelectorAll('[data-change-view]').forEach((button) => button.onclick = () => renderProjectChange(active.id, button.dataset.changeView));
}

function renderPluginsModal() {
  const pluginItems = plugins.list();
  const cards = pluginItems.length ? pluginItems.map((item) => `<div class="plugin-card-v2">
    <div class="feature-icon">${icon('plugin', 21)}</div>
    <div class="plugin-copy"><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.url)}</small><span class="plugin-status ${item.status}">${item.status === 'connected' ? `${item.tools.length} tools connected` : item.status === 'error' ? escapeHtml(item.error || 'Connection failed') : item.status}</span></div>
    <div class="plugin-actions"><select data-plugin-approval="${item.id}" title="Approval policy"><option value="ask" ${item.approval === 'ask' ? 'selected' : ''}>Ask</option><option value="allow" ${item.approval === 'allow' ? 'selected' : ''}>Allow</option><option value="deny" ${item.approval === 'deny' ? 'selected' : ''}>Deny</option></select><button class="secondary-button" data-plugin-connect="${item.id}">${item.status === 'connected' ? 'Disconnect' : 'Connect'}</button><button class="icon-button" data-plugin-remove="${item.id}" title="Remove plugin">${icon('x', 15)}</button></div>
  </div>`).join('') : '<div class="empty-panel">No external plugins connected yet.</div>';
  const builtinCount = project.definitions.length + artifacts.definitions.length;
  modalShell('Plugins', `<div class="plugins-summary"><div><strong>BlackRiver Tool Registry</strong><small>${builtinCount} built-in tools · ${plugins.toolDefinitions().length} external tools active</small></div><span class="status-pill connected">Registry active</span></div>
    <div class="plugin-builtin"><span>${icon('folder', 17)}</span><div><strong>Project Tools</strong><small>Filesystem read/search/write · project-scoped approvals</small></div><span class="status-pill connected">Built-in</span></div>
    <div class="plugin-builtin"><span>${icon('file', 17)}</span><div><strong>Artifact Tools</strong><small>Create, inspect, update and package Work artifacts</small></div><span class="status-pill connected">Built-in</span></div>
    <div class="project-subhead plugin-section-head"><strong>MCP servers</strong><span>${pluginItems.length}</span></div>
    <div class="plugin-list-v2">${cards}</div>
    <div class="plugin-add-v2"><div><strong>Add MCP server</strong><small>Browser Streamable HTTP endpoint. The server must allow browser CORS.</small></div><div class="plugin-add-fields"><input id="pluginName" placeholder="Name"><input id="pluginUrl" placeholder="http://127.0.0.1:3000/mcp"><button class="primary-button" id="addMcpPlugin">Add</button></div></div>`, { wide: true });

  document.getElementById('addMcpPlugin').onclick = async () => {
    try {
      const item = plugins.add({ name: document.getElementById('pluginName').value || 'MCP server', url: document.getElementById('pluginUrl').value });
      renderPluginsModal();
      try { await plugins.connect(item.id); toast(`${item.name} connected`, 'success'); } catch (error) { toast(errorMessage(error), 'error'); }
      renderPluginsModal();
    } catch (error) { toast(errorMessage(error), 'error'); }
  };
  document.querySelectorAll('[data-plugin-connect]').forEach((button) => button.onclick = async () => {
    const item = plugins.get(button.dataset.pluginConnect); if (!item) return;
    if (item.status === 'connected') { plugins.disconnect(item.id); renderPluginsModal(); return; }
    button.disabled = true;
    try { await plugins.connect(item.id); toast(`${item.name} connected`, 'success'); } catch (error) { toast(errorMessage(error), 'error'); }
    renderPluginsModal();
  });
  document.querySelectorAll('[data-plugin-approval]').forEach((select) => select.onchange = () => plugins.update(select.dataset.pluginApproval, { approval: select.value }));
  document.querySelectorAll('[data-plugin-remove]').forEach((button) => button.onclick = () => { plugins.remove(button.dataset.pluginRemove); renderPluginsModal(); });
}


function providerActive(providerId, modelId = '') {
  return runtime.isApi && runtime.selection.providerId === providerId && (!modelId || runtime.selection.modelId === modelId);
}

function providerStatusLabel(provider = {}) {
  try {
    const url = new URL(provider.baseUrl);
    if (provider.flavor === 'ollama' || url.hostname.toLowerCase() === 'ollama.com') return url.hostname.toLowerCase() === 'ollama.com' ? 'Ollama Cloud' : 'Ollama API';
    if (provider.flavor === 'nvidia' || url.hostname.toLowerCase() === 'integrate.api.nvidia.com') return 'NVIDIA NIM API';
    const local = ['127.0.0.1', 'localhost', '::1'].includes(url.hostname);
    return local ? 'Local API' : 'Remote API';
  } catch {
    return provider.flavor === 'ollama' ? 'Ollama API' : 'API';
  }
}

function providerCardMarkup(provider, index) {
  const models = provider.modelIds || [];
  const selected = providerActive(provider.id);
  const modelOptions = models.length
    ? models.map((id) => `<option value="${escapeHtml(id)}" ${(provider.lastModelId || models[0]) === id ? 'selected' : ''}>${escapeHtml(id)}</option>`).join('')
    : `<option value="">No discovered models</option>`;
  return `<article class="provider-card ${selected ? 'active' : ''}" data-provider-card="${escapeHtml(provider.id)}">
    <div class="provider-card-head">
      <span class="provider-icon">${icon('plugin', 18)}</span>
      <div><strong>${escapeHtml(provider.name)}</strong><small>${escapeHtml(providerStatusLabel(provider))} · ${escapeHtml(provider.baseUrl)}</small></div>
      <span class="provider-state">${selected ? 'Active' : models.length ? `${models.length} model${models.length === 1 ? '' : 's'}` : 'Saved'}</span>
    </div>
    <div class="provider-model-row">
      <select data-provider-model="${escapeHtml(provider.id)}">${modelOptions}</select>
      <button class="secondary-button compact" data-provider-refresh="${escapeHtml(provider.id)}">Refresh</button>
      <button class="primary-button compact" data-provider-use="${escapeHtml(provider.id)}" ${models.length ? '' : 'disabled'}>${selected ? 'Using' : 'Use'}</button>
      <button class="icon-button provider-remove" data-provider-remove="${escapeHtml(provider.id)}" title="Remove provider" aria-label="Remove provider">${icon('trash', 16)}</button>
    </div>
  </article>`;
}

