voice.addEventListener('phase', (event) => {
  const phase = event.detail?.phase;
  const label = event.detail?.label;
  if (!label) return;
  if (phase === 'loading-asr') {
    els.voiceStatusTitle.textContent = 'Preparing BlackRiver Voice';
    els.voiceStatusDetail.textContent = 'Loading Parakeet TDT';
  } else if (phase === 'asr-ready') {
    els.voiceStatusTitle.textContent = 'Voice ready';
    els.voiceStatusDetail.textContent = 'Parakeet TDT ready';
  } else if (phase === 'transcribing') {
    els.voiceStatusTitle.textContent = 'Transcribing';
    els.voiceStatusDetail.textContent = 'Parakeet TDT · multilingual';
  }
});
