function handleArtifactStoreUiEvent(item, { force = true } = {}) {
  const activeConv = store.activeConversation;
  if (item?.conversationId === activeConv?.id && store.state.mode === 'work') {
    renderArtifact(item, { force });
    return;
  }
  // Background Work may create/update an artifact while another conversation is
  // being inspected. Do not close, replace, or resize the viewer in that other
  // conversation; the new artifact will appear normally when its conversation
  // is opened again. ArtifactStore marks newly created viewer artifacts active,
  // so restore the visible artifact id when another Work pane is currently open.
  if (!els.artifactPane.classList.contains('hidden') && displayedArtifactId) {
    const visible = artifacts.get(displayedArtifactId);
    if (visible?.conversationId === activeConv?.id) artifacts.activeId = visible.id;
  }
  syncArtifactReopenButton();
}
artifacts.addEventListener('open', (e) => handleArtifactStoreUiEvent(e.detail, { force: true }));
