const CHAT_SYSTEM = `You are BlackRiver, a precise local AI assistant running privately on the user's device. Be useful, technically competent, concise by default, and never claim to have used tools you were not given. When downloadable file or ZIP tools are available and the user explicitly asks for a file, archive, package, project bundle, or downloadable deliverable, use the appropriate tool instead of merely pasting the complete payload inline.`;

function workSystem({ hasProject, hasArtifacts, projectName = '', projectInstructions = '', pinnedContext = [], projectFiles = [] }) {
  return `You are BlackRiver Work, an agentic local workspace assistant running privately on the user's device.

Behavior rules:
- Act instead of narrating what you are about to do.
- ${hasProject ? `The active project “${projectName || 'local project'}” is the source of truth for this Work conversation. When the user refers to “the app”, “the game”, “the page”, “the UI”, “the code”, “this”, a screenshot, a bug, or a requested change, assume they mean the active project unless they explicitly ask for an Artifact.` : 'No project folder is connected. Do not claim to inspect a filesystem. Use artifacts for creation tasks.'}
- ${hasProject ? 'Inspect the project before answering implementation/debugging requests: list/search/read the relevant on-disk files, then make targeted edits. Never decide that the project is empty merely because the current conversation has no BlackRiver artifacts.' : 'For standalone apps, games, webpages, demos, documents, and code that do not need an existing project folder, create or update a BlackRiver artifact.'}
- ${hasProject ? 'Do not create a replacement Artifact for an existing project task unless the user explicitly asks for an Artifact/preview. Edit the project files themselves.' : 'Interactive artifacts should be one self-contained HTML document with inline CSS/JS unless the user asks otherwise.'}
- When the user explicitly asks for a multi-file project, package, archive, starter repo, or ZIP and no editable project is active, use the downloadable ZIP artifact tool instead of forcing everything into one HTML document.
- ${hasProject && projectFiles?.length ? `Known project files from the latest filesystem scan:\n${projectFiles.slice(0, 120).map((item) => `- ${item}`).join('\n')}` : hasProject ? 'The project is connected but no files were indexed yet; use list_directory before concluding it is empty.' : ''}
- ${projectInstructions ? `Project instructions (follow these for this project):\n${projectInstructions}` : 'No project-specific instructions are set.'}
- ${pinnedContext?.length ? `Pinned project context:\n${pinnedContext.map((item) => `- ${item}`).join('\n')}` : 'No pinned project context is set.'}
- ${hasArtifacts ? 'Existing BlackRiver artifacts may be read and updated when the user explicitly refers to them.' : 'There may be no existing BlackRiver artifacts yet; that says nothing about files in an active project.'}
- Never invent tool results or claim a write succeeded unless the tool result confirms it.
- If a write is denied, continue without pressuring the user.
- Tool calls should contain the complete required arguments. When calling a tool, do not add a suffix after the tool call.
- After completing tool work, give a short useful result summary rather than repeating the implementation in chat.`;
}

function toOaiMessages(messages) {
  return messages
    .filter((m) => m.role === 'user' || m.role === 'assistant')
    .map((m) => {
      const out = { role: m.role, content: m.content || '' };
      // llama.cpp's reasoning parser accepts reasoning_content on assistant
      // messages. Keeping it in-context matters for thinking models across turns.
      if (m.role === 'assistant' && m.reasoning) out.reasoning_content = m.reasoning;
      return out;
    });
}

function mergeToolDelta(map, tc) {
  const index = tc.index ?? 0;
  if (!map[index]) map[index] = { id: '', name: '', arguments: '' };
  if (tc.id) map[index].id = tc.id;
  if (tc.function?.name) map[index].name += tc.function.name;
  if (tc.function?.arguments) map[index].arguments += tc.function.arguments;
}

function mergeReasoning(base = '', extra = '') {
  const a = String(base || '').trim();
  const b = String(extra || '').trim();
  if (!b) return a;
  if (!a) return b;
  if (a.includes(b)) return a;
  if (b.includes(a)) return b;
  return `${a}\n${b}`.trim();
}

// Incremental fallback for models/templates that leave <think> markup in content.
// Crucially, an unterminated <think> block is treated as live reasoning instead
// of being flashed to the user as raw assistant text while generation is running.
function splitInlineReasoning(raw = '') {
  let text = String(raw || '').replace(/<\|im_(?:start|end)\|>/g, '');
  let reasoning = '';
  const open = text.search(/<think>/i);
  if (open >= 0) {
    const before = text.slice(0, open);
    const afterOpen = text.slice(open).replace(/^<think>/i, '');
    const close = afterOpen.search(/<\/think>/i);
    if (close >= 0) {
      reasoning = afterOpen.slice(0, close).trim();
      text = `${before}${afterOpen.slice(close).replace(/^<\/think>/i, '')}`;
    } else {
      reasoning = afterOpen.trim();
      text = before;
    }
  } else if (/<\/think>/i.test(text)) {
    const parts = text.split(/<\/think>/i);
    const visible = parts.pop() || '';
    reasoning = parts.join('\n').trim();
    text = visible;
  }
  text = text.replace(/<\/?think>/gi, '').trimStart();
  return { content: text, reasoning };
}

function stripToolMarkup(text = '') {
  return String(text)
    .replace(/<tool_call>[\s\S]*?<\/tool_call>/gi, '')
    .replace(/<function=[^>]+>[\s\S]*?<\/function>/gi, '')
    .trim();
}

function parseScalar(value) {
  const s = String(value ?? '').trim();
  if (!s) return '';
  try { return JSON.parse(s); } catch {}
  if (s === 'true') return true;
  if (s === 'false') return false;
  if (s === 'null') return null;
  if (/^-?\d+(?:\.\d+)?$/.test(s)) return Number(s);
  return s;
}

function parseFallbackToolCalls(raw = '') {
  const calls = [];
  const blocks = String(raw).match(/<tool_call>[\s\S]*?<\/tool_call>/gi) || [];
  for (const block of blocks) {
    const fn = block.match(/<function=([^>]+)>/i)?.[1]?.trim();
    if (!fn) continue;
    const args = {};
    const paramRegex = /<parameter=([^>]+)>\s*([\s\S]*?)\s*<\/parameter>/gi;
    let m;
    while ((m = paramRegex.exec(block))) args[m[1].trim()] = parseScalar(m[2]);
    calls.push({ id: '', name: fn, arguments: JSON.stringify(args) });
  }
  return calls;
}

function shouldRequireTool(mode, prompt, tools, { hasProject = false, hasAttachment = false } = {}) {
  if (!tools.length) return false;
  const text = String(prompt || '');
  const creationIntent = /\b(create|build|make|implement|write|generate|develop|remake|redesign|produce|craft|code|design|prototype|export|package)\b/i.test(text);
  if (mode === 'work' && hasProject) {
    const projectTask = hasAttachment || /\b(problem|probleme|issue|bug|broken|wrong|incorrect|display|render|layout|clipp|missing|error|crash|fail|fix|repair|edit|change|modify|update|improve|app|game|website|webpage|ui|code|file)\b/i.test(text);
    if (projectTask && tools.some((tool) => ['list_directory', 'file_glob_search', 'read_file', 'grep_search', 'get_info'].includes(tool.function?.name))) return true;
  }
  if (!creationIntent) return false;
  if (mode === 'work') {
    // If routing selected a deliverable creator for a creation request, require it
    // on the first turn. Project read/edit tools otherwise remain auto.
    return tools.some((tool) => ['create_artifact', 'create_downloadable_file', 'create_zip_artifact'].includes(tool.function?.name));
  }
  if (mode === 'chat') {
    const explicitDownload = /\b(zip|archive|bundle|download|downloadable|file|script|document|config|csv|json|markdown|txt|pdf)\b/i.test(text);
    return explicitDownload && tools.some((tool) => ['create_downloadable_file', 'create_zip_artifact'].includes(tool.function?.name));
  }
  return false;
}

function titleFromArtifactContent(content = '', prompt = '') {
  const htmlTitle = String(content).match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1]
    ?.replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (htmlTitle) return htmlTitle.slice(0, 120);

  const cleanedPrompt = String(prompt || '')
    .replace(/^(?:please\s+)?(?:create|build|make|implement|write|generate|develop|remake|redesign|produce|craft)\s+/i, '')
    .replace(/\s+/g, ' ')
    .trim();
  if (cleanedPrompt) {
    const compact = cleanedPrompt.length > 72 ? `${cleanedPrompt.slice(0, 69).trim()}…` : cleanedPrompt;
    return compact.charAt(0).toUpperCase() + compact.slice(1);
  }
  return 'Work artifact';
}

function recoverDirectArtifact(raw = '', prompt = '') {
  const source = String(raw || '').trim();
  if (!source) return null;

  // Some local models occasionally ignore tool_choice=required and emit the
  // complete deliverable as a Markdown code fence instead. Work should still
  // behave like an artifact workspace, not dump hundreds of lines into chat.
  const fenced = [...source.matchAll(/```([^\n`]*)\n([\s\S]*?)```/g)]
    .map((match) => ({ language: String(match[1] || '').trim().toLowerCase(), content: String(match[2] || '').trim() }))
    .filter((entry) => entry.content.length >= 48)
    .sort((a, b) => b.content.length - a.content.length)[0] || null;

  let content = fenced?.content || '';
  let language = fenced?.language || '';

  if (!content) {
    const htmlStart = source.search(/<!doctype\s+html|<html(?:\s|>)/i);
    if (htmlStart >= 0) {
      const tail = source.slice(htmlStart);
      const endMatch = tail.match(/<\/html>\s*$/i);
      content = endMatch ? tail.slice(0, endMatch.index + endMatch[0].length).trim() : tail.trim();
      language = 'html';
    }
  }

  if (!content || content.length < 48) return null;

  const htmlLike = /<!doctype\s+html|<html(?:\s|>)|<body(?:\s|>)/i.test(content) || language === 'html';
  const knownLanguages = new Set(['javascript', 'js', 'typescript', 'ts', 'python', 'py', 'css', 'json', 'markdown', 'md', 'html']);
  const normalizedLanguage = knownLanguages.has(language) ? language : '';

  return {
    title: titleFromArtifactContent(content, prompt),
    type: htmlLike ? 'html' : (normalizedLanguage === 'markdown' || normalizedLanguage === 'md' ? 'markdown' : 'code'),
    language: htmlLike ? 'html' : normalizedLanguage,
    content,
  };
}


function downloadToolIntent(prompt = '') {
  const text = String(prompt || '').trim();
  if (!text) return { use: false, explicit: false, zip: false, file: false, projectish: false };
  const creation = /\b(create|build|make|write|generate|produce|export|package|give|prepare|save|code|develop|implement)\b/i.test(text);
  const zip = /\b(zip|archive|bundle|package|starter repo|repository|multi[- ]file|multiple files|project files|folder structure|source tree)\b/i.test(text);
  const file = /\b(file|download|downloadable|script|document|config|configuration|csv|json|markdown|md|txt|python file|javascript file|typescript file|html file|pdf)\b/i.test(text);
  const projectish = /\b(project|repo|codebase|starter|package)\b/i.test(text);
  const explicit = creation && (zip || file);
  return { use: creation && (zip || file || projectish), explicit, zip: creation && zip, file: creation && file, projectish: creation && projectish };
}

function workToolIntent(prompt = '', { hasProject = false, hasArtifacts = false } = {}) {
  const text = String(prompt || '').trim();
  if (!text) return { useTools: false, artifact: false, project: false, creation: false };

  const creation = /\b(create|build|make|implement|write|generate|develop|remake|redesign|produce|craft|code|design|prototype)\b/i.test(text);
  const mutation = /\b(edit|update|change|modify|fix|repair|improve|revise|refactor|replace|remove|add|correct|adjust)\b/i.test(text);
  const genericDeliverable = /\b(game|app|website|webpage|html|document|file|code|script|component|prototype|ui|layout)\b/i.test(text);
  const explicitArtifact = /\b(artifact|artifact viewer|blackriver artifact|standalone artifact|preview artifact)\b/i.test(text);
  const projectMention = /\b(project|repo|repository|folder|file|codebase|source|src|directory|grep|search files|read file)\b/i.test(text);
  const inspect = /\b(list|show|open|read|inspect|find|search|check|look)\b/i.test(text);
  const problem = /\b(problem|probleme|issue|bug|broken|wrong|incorrect|display|render|clipp|missing|error|crash|fail)\b/i.test(text);

  // Once a Project is active, it is the Work lane's source of truth. Project
  // tools stay available for every non-empty request so natural prompts such as
  // “the left side is wrong, look at the screenshot” cannot accidentally route
  // to an empty Artifact lane. Artifact tools become opt-in while a project is
  // active; otherwise generic app/game/code creation still routes to artifacts.
  const useProjectTools = hasProject;
  const useArtifactTools = hasProject
    ? explicitArtifact
    : (explicitArtifact || genericDeliverable || creation || (hasArtifacts && (creation || mutation || inspect || problem)));
  const useTools = useProjectTools || useArtifactTools || projectMention || mutation || inspect || problem;
  return { useTools, artifact: useArtifactTools, project: useProjectTools, creation };
}

function toolActivityLabel(name = '') {
  const labels = {
    create_artifact: 'Building artifact',
    update_artifact: 'Updating artifact',
    read_artifact: 'Reading artifact',
    list_artifacts: 'Checking artifacts',
    create_downloadable_file: 'Preparing file',
    create_zip_artifact: 'Packaging files',
    list_directory: 'Inspecting project',
    file_glob_search: 'Finding files',
    read_file: 'Reading file',
    grep_search: 'Searching project',
    write_file: 'Writing file',
    edit_file: 'Editing file',
    replace_in_file: 'Editing file',
    get_info: 'Checking project',
  };
  return labels[name] || `Using ${String(name).replaceAll('_', ' ')}`;
}

function safeJson(text) {
  try { return JSON.parse(text || '{}'); }
  catch { return null; }
}

function normalizeMetrics(chunk, contextSize = 0) {
  const timings = chunk?.timings || {};
  const usage = chunk?.usage || {};
  const progress = chunk?.prompt_progress || null;
  const promptTokens = Number(usage.prompt_tokens ?? ((timings.cache_n || 0) + (timings.prompt_n || 0))) || 0;
  const completionTokens = Number(usage.completion_tokens ?? timings.predicted_n) || 0;
  const used = Number(usage.total_tokens) || (promptTokens + completionTokens);
  const ctx = Number(contextSize) || 0;
  return {
    promptTokens,
    completionTokens,
    used,
    remaining: ctx ? Math.max(0, ctx - used) : 0,
    contextSize: ctx,
    cachedTokens: Number(timings.cache_n || usage.prompt_tokens_details?.cached_tokens) || 0,
    promptTps: Number(timings.prompt_per_second) || 0,
    generationTpsLive: Number(timings.predicted_per_second_3s) || 0,
    generationTpsAverage: Number(timings.predicted_per_second) || 0,
    generationTps: Number(timings.predicted_per_second_3s || timings.predicted_per_second) || 0,
    promptProgress: progress ? {
      total: Number(progress.total) || 0,
      cache: Number(progress.cache) || 0,
      processed: Number(progress.processed) || 0,
      timeMs: Number(progress.time_ms) || 0,
    } : null,
  };
}


const REASONING_BUDGETS = Object.freeze({
  low: 512,
  medium: 2048,
  high: 8192,
});

function reasoningRequestOptions(profile = 'medium') {
  const effort = ['off', 'low', 'medium', 'high'].includes(profile) ? profile : 'medium';
  if (effort === 'off') {
    // Match llama.cpp WebUI semantics: disable thinking through the chat
    // template rather than forcing a zero-token budget.
    return {
      chat_template_kwargs: { enable_thinking: false },
      reasoning_control: true,
    };
  }
  return {
    chat_template_kwargs: { enable_thinking: true },
    thinking_budget_tokens: REASONING_BUDGETS[effort],
    reasoning_control: true,
  };
}

export class AgentHarness {
  constructor(runtime, project, artifacts, toolRegistry = null) {
    this.runtime = runtime;
    this.project = project;
    this.artifacts = artifacts;
    this.toolRegistry = toolRegistry;
    this.maxTurns = 12;
  }

  toolDefinitions(mode, { prompt = '', conversationId = null } = {}) {
    const artifactDefs = this.artifacts.definitions;
    const downloadDefs = this.artifacts.downloadDefinitions;
    const downloadIntent = downloadToolIntent(prompt);

    if (mode === 'chat') {
      if (!downloadIntent.use) return [];
      if (downloadIntent.projectish && !downloadIntent.explicit) return downloadDefs;
      return downloadDefs.filter((tool) => {
        const name = tool.function?.name;
        if (downloadIntent.zip) return name === 'create_zip_artifact';
        return name === 'create_downloadable_file';
      });
    }
    if (mode !== 'work') return [];

    const hasProject = !!this.project.root;
    const hasArtifacts = this.artifacts.list(conversationId).some((item) => ['html', 'code', 'text', 'markdown'].includes(item.type));
    const intent = workToolIntent(prompt, { hasProject, hasArtifacts });
    const pluginDefs = this.toolRegistry ? this.toolRegistry.definitions({ sourceIds: ['plugins'], context: { mode, projectId: this.project.id } }) : [];
    if (!intent.useTools && !downloadIntent.explicit && !pluginDefs.length) return [];

    const viewerDefs = this.artifacts.viewerDefinitions;
    const projectDefs = hasProject ? this.project.definitions : [];
    const tools = [];

    if (downloadIntent.explicit) {
      tools.push(...downloadDefs.filter((tool) => downloadIntent.zip ? tool.function?.name === 'create_zip_artifact' : tool.function?.name === 'create_downloadable_file'));
    } else if (intent.artifact) {
      if (!hasArtifacts && intent.creation) {
        // Fresh standalone creation only needs one schema on the first turn.
        const create = viewerDefs.find((tool) => tool.function?.name === 'create_artifact');
        if (create) tools.push(create);
      } else {
        tools.push(...viewerDefs);
      }
    }

    if (intent.project) tools.push(...projectDefs);
    if (pluginDefs.length) tools.push(...pluginDefs);

    const seen = new Set();
    return tools.filter((tool) => {
      const name = tool.function?.name;
      if (!name || seen.has(name)) return false;
      seen.add(name);
      return true;
    });
  }

  async executeTool(name, args, context) {
    const projectId = context.projectId !== undefined ? context.projectId : this.project.id;
    if (this.toolRegistry) return this.toolRegistry.execute(name, args, { ...context, projectId });
    if (this.artifacts.definitions.some((t) => t.function.name === name)) {
      return this.artifacts.execute(name, args, { conversationId: context.conversationId, projectId });
    }
    return this.project.execute(name, args, { approve: context.approve });
  }

  async run({ mode, messages, attachment, conversationId, projectId: requestedProjectId = undefined, reasoningProfile = 'medium', onText, onReasoning, onTool, onArtifact, onState, onMetrics, approve }) {
    const lastUser = [...messages].reverse().find((m) => m.role === 'user')?.content || '';
    const projectId = requestedProjectId !== undefined ? requestedProjectId : (this.project.id || null);
    const projectRecord = projectId ? this.project.store?.get(projectId) : null;
    const hasProject = !!projectId && (!!this.project.root || !!projectRecord?.handle);
    let projectSnapshot = null;
    if (mode === 'work' && hasProject) {
      try { projectSnapshot = await this.project.projectSnapshot(projectId, { refresh: true, maxEntries: 120 }); } catch {}
    }
    const tools = this.toolDefinitions(mode, { prompt: lastUser, conversationId });
    const hasArtifacts = this.artifacts.list(conversationId).some((item) => ['html', 'code', 'text', 'markdown'].includes(item.type));
    const system = mode === 'work' ? workSystem({ hasProject, hasArtifacts, projectName: projectRecord?.name || this.project.name, projectInstructions: projectRecord?.instructions || this.project.instructions, pinnedContext: projectRecord?.pinnedContext || this.project.pinnedContext, projectFiles: projectSnapshot?.files || projectRecord?.fileIndex?.filter((entry) => entry.kind === 'file').map((entry) => entry.path) || [] }) : CHAT_SYSTEM;
    const oai = [{ role: 'system', content: system }, ...toOaiMessages(messages)];

    if (attachment && oai.length > 1) {
      const last = oai.at(-1);
      if (last.role === 'user') {
        last.content = [
          { type: attachment.type, data: attachment.data, mime: attachment.mime || '' },
          { type: 'text', text: typeof last.content === 'string' ? last.content : '' },
        ];
      }
    }

    const requireToolInitially = shouldRequireTool(mode, lastUser, tools, { hasProject, hasAttachment: !!attachment });
    let visible = '';
    let reasoningVisible = '';
    let lastMetrics = null;
    const executedFingerprints = new Map();

    for (let turn = 0; turn < this.maxTurns; turn++) {
      onState?.({ phase: 'prefill', label: turn === 0 ? 'Reading context' : 'Continuing' });
      let rawContent = '';
      let turnReasoning = '';
      let finishReason = null;
      let sawVisibleContent = false;
      let sawReasoning = false;
      const toolMap = {};
      const announcedTools = new Set();
      // On a creation turn where Work explicitly requires an artifact tool, keep
      // direct assistant content buffered until we know whether the model obeyed
      // the tool call. This prevents a non-compliant model from streaming an
      // entire HTML document into the conversation before we can recover it.
      const bufferRequiredArtifactContent = turn === 0 && requireToolInitially && tools.some((tool) => tool.function?.name === 'create_artifact');

      await this.runtime.chat({
        messages: oai,
        ...reasoningRequestOptions(reasoningProfile),
        ...(tools.length ? {
          tools,
          tool_choice: turn === 0 && requireToolInitially ? 'required' : 'auto',
        } : {}),
      }, (chunk) => {
        const metrics = normalizeMetrics(chunk, this.runtime.contextSize);
        if (metrics.promptProgress || metrics.generationTps || metrics.promptTps || metrics.used) {
          lastMetrics = {
            ...(lastMetrics || {}),
            ...metrics,
            promptTps: metrics.promptTps || lastMetrics?.promptTps || 0,
            generationTpsLive: metrics.generationTpsLive || lastMetrics?.generationTpsLive || 0,
            generationTpsAverage: metrics.generationTpsAverage || lastMetrics?.generationTpsAverage || 0,
            generationTps: metrics.generationTps || lastMetrics?.generationTps || 0,
            promptProgress: metrics.promptProgress || lastMetrics?.promptProgress || null,
          };
          onMetrics?.(lastMetrics);
          if (metrics.promptProgress && !sawReasoning && !sawVisibleContent) {
            const { processed, total } = metrics.promptProgress;
            const pct = total > 0 ? Math.min(100, Math.round((processed / total) * 100)) : 0;
            onState?.({ phase: 'prefill', label: pct > 0 && pct < 100 ? `Reading context · ${pct}%` : 'Reading context' });
          }
        }

        const choice = chunk?.choices?.[0];
        if (!choice) return;
        finishReason = choice.finish_reason ?? finishReason;
        const delta = choice.delta || {};

        // llama.cpp reasoning_format=deepseek streams this field independently.
        // Wllama forwards the JSON even though older TS typings did not enumerate it.
        const reasoningDelta = delta.reasoning_content ?? delta.reasoning ?? '';
        if (reasoningDelta) {
          turnReasoning += reasoningDelta;
          sawReasoning = true;
          onState?.({ phase: 'thinking', label: 'Thinking' });
        }

        if (delta.content) {
          rawContent += delta.content;
          const inline = splitInlineReasoning(rawContent);
          if (inline.reasoning) {
            sawReasoning = true;
            onState?.({ phase: 'thinking', label: 'Thinking' });
          }
          if (inline.content) {
            sawVisibleContent = true;
            onState?.({ phase: 'responding', label: 'Responding' });
          }
        }

        for (const tc of delta.tool_calls || []) {
          mergeToolDelta(toolMap, tc);
          const entry = toolMap[tc.index ?? 0];
          if (entry?.name && !announcedTools.has(entry.name)) {
            announcedTools.add(entry.name);
            onState?.({ phase: 'tool', label: toolActivityLabel(entry.name) });
          }
        }

        const inline = splitInlineReasoning(rawContent);
        const cleanContent = stripToolMarkup(inline.content);
        const currentReasoning = mergeReasoning(reasoningVisible, mergeReasoning(turnReasoning, inline.reasoning));
        onText?.(visible + (bufferRequiredArtifactContent ? '' : cleanContent));
        onReasoning?.(currentReasoning);
      });

      const inline = splitInlineReasoning(rawContent);
      const cleanContent = stripToolMarkup(inline.content);
      turnReasoning = mergeReasoning(turnReasoning, inline.reasoning);
      reasoningVisible = mergeReasoning(reasoningVisible, turnReasoning);

      let calls = Object.values(toolMap).filter((tc) => tc.name);
      if (!calls.length) calls = parseFallbackToolCalls(rawContent);

      if (!calls.length) {
        if (bufferRequiredArtifactContent) {
          const recovered = recoverDirectArtifact(cleanContent, lastUser);
          if (recovered) {
            const toolName = 'create_artifact';
            onTool?.({ phase: 'call', name: toolName, args: recovered });
            onState?.({ phase: 'tool', label: 'Building artifact' });
            let result;
            try {
              result = await this.executeTool(toolName, recovered, { conversationId, approve, projectId });
            } catch (error) {
              result = { error: error?.message || String(error || 'Artifact recovery failed') };
            }
            onTool?.({ phase: 'result', name: toolName, args: recovered, result });
            if (!result?.error && result?.artifact_id) {
              this.artifacts.open(result.artifact_id);
              const item = this.artifacts.get(result.artifact_id);
              onArtifact?.(item);
              visible += `Created **${item?.title || recovered.title}** and opened it in the Artifact Viewer.`;
              onText?.(visible);
              onReasoning?.(reasoningVisible);
              onState?.({ phase: 'done', label: 'Artifact ready' });
              return {
                content: visible.trim(),
                reasoning: reasoningVisible,
                finishReason: finishReason || 'stop',
                metrics: lastMetrics,
                recoveredArtifact: true,
                artifactId: result.artifact_id,
              };
            }
          }
        }

        visible += cleanContent;
        onText?.(visible);
        onReasoning?.(reasoningVisible);
        onState?.({ phase: 'done', label: 'Done' });
        return { content: visible.trim(), reasoning: reasoningVisible, finishReason, metrics: lastMetrics };
      }

      if (cleanContent && !/^(i(?:'ll| will| am)|let me|i'm going to)\b/i.test(cleanContent.trim())) {
        visible += `${cleanContent.trim()}\n`;
      }

      const assistantToolMessage = {
        role: 'assistant',
        content: cleanContent || null,
        ...(turnReasoning ? { reasoning_content: turnReasoning } : {}),
        tool_calls: calls.map((tc, index) => ({
          id: tc.id || `call_${turn}_${index}_${Math.random().toString(16).slice(2, 8)}`,
          type: 'function',
          function: { name: tc.name, arguments: tc.arguments || '{}' },
        })),
      };
      oai.push(assistantToolMessage);

      for (const call of assistantToolMessage.tool_calls) {
        const args = safeJson(call.function.arguments);
        if (args === null) {
          const result = { error: 'Invalid JSON arguments returned by the model.' };
          oai.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(result) });
          onTool?.({ phase: 'result', name: call.function.name, args: {}, result });
          continue;
        }

        const fingerprint = `${call.function.name}:${JSON.stringify(args)}`;
        const count = (executedFingerprints.get(fingerprint) || 0) + 1;
        executedFingerprints.set(fingerprint, count);
        if (count > 2) {
          const result = { error: 'Duplicate tool call suppressed. Use the existing result and continue.' };
          oai.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(result) });
          onTool?.({ phase: 'result', name: call.function.name, args, result });
          continue;
        }

        onTool?.({ phase: 'call', name: call.function.name, args });
        onState?.({ phase: 'tool', label: toolActivityLabel(call.function.name) });
        let result;
        try {
          result = await this.executeTool(call.function.name, args, { conversationId, approve, projectId });
        } catch (error) {
          result = { error: error?.message || String(error || 'Tool failed') };
        }
        onTool?.({ phase: 'result', name: call.function.name, args, result });
        if (result?.artifact_id) {
          if (result?.viewer === 'opened') this.artifacts.open(result.artifact_id);
          onArtifact?.(this.artifacts.get(result.artifact_id));
        }
        oai.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(result) });
      }
    }

    onState?.({ phase: 'done', label: 'Turn limit reached' });
    return {
      content: visible.trim() || 'I reached the Work turn limit before completing the task.',
      reasoning: reasoningVisible,
      finishReason: 'length',
      maxTurnsReached: true,
      metrics: lastMetrics,
    };
  }
}
